INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3014, 'Playas', 'Los Saladares', 'Situada en el extremo sur de Alicante, en una zona residencial tranquila, en un área de humedales de alto interés medioambiental, antiguamente lugar de explotación salinera. Permite disfrutar de baños', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3014, 'Playas', 'El Postiguet', 'Playa situada en pleno casco urbano alicantino, a los pies del castillo de Santa Bárbara, que toma su nombre de un pequeño postigo de acceso a la población. Bordeada por un paseo marítimo cuajado de p', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3018, 'Playas', 'L''Espigó', 'Céntrica playa de reciente inauguración, de aguas tranquilas por los espigones que la protegen.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3018, 'Playas', 'Cap Blanc', 'La Playa de Cap Blanc, al sur del pueblo de Altea, es la de mayor extensión de su término, fundiéndose con la Playa del Albir, en el término vecino, permitiendo disfrutar de grandes zonas de baño de d', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3018, 'Playas', 'La Roda', 'La Playa de La Roda, ubicada junto al casco urbano de Altea, aparece como playa urbana donde se dispone de todo tipo de servicios para disfrutar de una gran extensión de arena y grava y de sus tranqui', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3031, 'Playas', 'Playa de Poniente', 'La Playa de Poniente ocupa desde el casco antiguo hasta la vecina Cala de Finestrat. Esta playa también goza de la finura de su arena, la limpieza diaria y la calidad de sus servicios, como la Playa d', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3031, 'Playas', 'Cala del Mal Pas', 'Entre la Playa de Poniente y el casco antiguo se encuentra esta pequeña calita conocida como Cala del Mal Pas a la que se accede desde el puerto o desde unas escaleras que bajan directamente desde el ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3031, 'Playas', 'Playa de Levante', 'La Playa de Levante, con dos kilómetros de extensión, destaca por la finura de su arena y la calidad de sus servicios. Desde La Plaza del Castillo se puede acceder a esta playa por típicas calles estr', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3041, 'Playas', 'Cala L''Advocat', 'Esta playa presenta un carácter rocoso, como muchas de los alrededores.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3041, 'Playas', 'El Baladrar', 'Cala rodeada de pinos y protegida de los vientos de levante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3042, 'Playas', 'Moraig', 'Cala con los servicios básicos dentro de un litoral escarpado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3047, 'Playas', 'Puerto Blanco', 'Playa ubicada en las inmediaciones del puerto', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3050, 'Playas', 'Muchavista', 'Extensa playa de dorada arena en la parte sur el municipio que, en época estival, ofrece un amplio programa de actividades.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3050, 'Playas', 'Carrer La Mar', 'El núcleo de Carrer del Mar que da nombre a esta playa se encuentra en la fachada marítima del pueblo de El Campello. Es aquí donde antiguamente estaba ubicado el barrio de pescadores y que en la actu', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3063, 'Playas', 'Les Rotes', 'Les Rotes, localizada al sur de Denia, constituye unas pequeñas calas con parajes de increíble belleza.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3065, 'Playas', 'La Marina', 'Las playas de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas y multitud de servicios, así como de zonas de gran valor ecológico, como son los ecosistem', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3065, 'Playas', 'El Pinet', 'El sur de Elche dispone de dos playas de características similares, El Pinet y La Marina, amplias bandas de arena dorada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3065, 'Playas', 'Carabassí', 'Las playas del norte de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas, así como de zonas de gran valor ecológico, como son los ecosistemas de dunas de', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3069, 'Playas', 'Finestrat', 'Finestrat, típico pueblo mediterráneo del interior, posee este pequeño segmento de litoral que conforma su playa gracias a su contribución a la defensa del litoral contra los piratas berberiscos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3076, 'Playas', 'Les Ortigues', 'Las Playas del Campo y Les Ortigues, una a continuación de la otra, constituyen una amplia franja de arena dorada que permite disfrutar de grandes paseos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3076, 'Playas', 'El Campo', 'Las Playas del Campo y Les Ortigues, una a continuación de la otra, constituyen una amplia franja de arena dorada que permite disfrutar de grandes paseos', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3076, 'Playas', 'El Moncayo', 'De las magníficas playas del litoral guardamarenco, la Playa del Moncayo y la Playa de Los Tusales, junto a la desembocadura del Segura, son un buen ejemplo de playas vírgenes de gran calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3082, 'Playas', 'Primer Montañar', 'Playa urbana de gran extensión compuesta especialmente por rocas y grava, donde pueden practicarse deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3082, 'Playas', 'La Grava', 'Esta playa se localiza en la zona urbana de Aduanas del Mar y presenta un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3082, 'Playas', 'Pope', 'Esta pequeña playa de grava esta enclavada en las proximidades de la Reserva Marina del Cabo de San Antonio.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3099, 'Playas', 'Cala del Bosque', 'Cala del Bosque y Cala Cerrada son conocidas como La Zenia por estar ubicadas en el centro del complejo urbanístico que le da nombre, dotando a estas playas de todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3099, 'Playas', 'Cala Cerrada', 'Cala Cerrada y Cala del Bosque son conocidas como La Zenia, ubicadas en el complejo urbanístico del mismo nombre, presentando gran disponibilidad de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3099, 'Playas', 'Mil Palmeras', 'Playa natural ubicada en una zona urbana, donde se dispone de todo tipo de servicios necesarios para su uso.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3121, 'Playas', 'Tamarit', 'Playa urbana en la parte más occidental del núcleo urbano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3121, 'Playas', 'Lisa', 'Ancha playa de arena oscura y alta ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3128, 'Playas', 'Les Playetes', 'Esta pequeña playa ofrece unas aguas transparentes y arena fina de color oscuro mezclada con rocas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3128, 'Playas', 'La Ampolla', 'La Ampolla es la playa más famosa de Teulada, situada junto al castillo, con arena fina y aguas transparentes.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3133, 'Playas', 'La Mata', 'Es la playa más extensa de Torrevieja y se encuentra rodeada de urbanizaciones. Cercana al Parque del Molino del Agua.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3133, 'Playas', 'Torrelamata', 'Playa con atractivos para el buceo y la práctica de deportes náuticos', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3133, 'Playas', 'Cala de las Piteras', 'En la zona sur, en el límite del término de Orihuela, en una zona semiurbana, se encuentra esta cala rodeada de rocas y con la vegetación típica del Mediterráneo, apta para la pesca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3139, 'Playas', 'El Torres', 'Entre las numerosas playas de las que disfruta La Vila Joiosa, la del Torres tiene el atractivo añadido de ser allí donde se levanta la torre romana-funeraria de Hércules.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3902, 'Playas', 'El Mojón', 'Es la última playa del litoral costero de Pilar de la Horadada, en su límite con Murcia', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3902, 'Playas', 'Las Higuericas', 'Esta playa de arena fina se encuentra apartada de zonas urbanizadas, pero con gran afluencia de visitantes que disfrutan de la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (3902, 'Playas', 'Las Villas', 'Playa que presenta un alto grado de ocupación, sobre todo en la temporada estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4003, 'Playas', 'Playa de Poniente', 'Extensa playa con un alto grado de ocupación por la cantidad de servicios que ofrece y por ser una de las playas más limpias de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4013, 'Playas', 'Las Salinas de Cabo de Gata', 'Playa con una excelente arena, localizada muy cerca de una zona de marismas por lo que alberga gran cantidad de aves muy interesantes. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Ní', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4032, 'Playas', 'El Ancón', 'Playa urbana con gran calidad y disponibilidad de sus servicios e infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4035, 'Playas', 'Pozo del Esparto', 'Esta playa de carácter urbano toma su nombre del núcleo urbano de Pozo del Esparto que se extiende a lo largo de toda la franja de arena y grava.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4041, 'Playas', 'El Palmer', 'Playa de piedras que dispone de los servicios que ofrece el único hotel cercano a la playa y que son de uso exclusivo para sus clientes. La playa esta ocupada parcialmente por una escollera. Existe un', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4049, 'Playas', 'Garrucha', 'Playa urbana ideal para familias, totalmente equipada y con servicios de calidad. Está amurallada por una balaustrada de mármol blanco que convierte al paseo marítimo único de Europa con estas caracte', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4064, 'Playas', 'Cueva del Lobo', 'Esta playa debe su nombre a una de las primeras edificaciones que se realizaron en este lugar, en torno a los años 60 y propiedad de un famoso pianista que bautizó la casa con este curioso nombre.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4064, 'Playas', 'El Cantal', 'Playa de carácter urbano que dispone de todo tipo de servicios e instalaciones que contribuyen al alto grado de ocupación que presenta. Sobre su arena encontramos la carismática gran piedra del cantal', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4066, 'Playas', 'Aguamarga', 'La Playa de Aguamarga dispone de los servicios e instalaciones necesarias para el veraneo familiar. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, declarado Reserva de la Biosfe', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4075, 'Playas', 'Cala Cerrada', 'Cala aislada en forma de concha muy atractiva por las rocas que la forman y sobre todo por la transparencia de sus aguas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4075, 'Playas', 'Cala de la Tía Antonia', 'Pequeña cala de arena dorada muy frecuentada por familias y habitantes del pueblo en el que se encuentra, San Juan de los Terrenos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4079, 'Playas', 'Aguadulce', 'La Playa de Aguadulce es una de las playas con mayor grado de ocupación del sur de Almería y que cuenta con una gran oferta de ocio para los turistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4079, 'Playas', 'La Bajadilla', 'Playa totalmente equipada, localizada a continuación de la playa  Urbanización Roquetas de Mar. Presenta un alto grado de ocupación, aunque sin saturaciones.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4100, 'Playas', 'El Playazo', 'El Playazo es de las playas más destacadas de la zona por disponer de un completo aquipamiento para el uso turístico. La Playa Naturista se desarrolla frente a los establecimientos hoteleros donde el ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4100, 'Playas', 'Las Marinas-Bolaga', 'Extensa playa lineal que está dotada con todo tipo de servicios e infraestructuras y que cuenta con diversos reconocimientos y sellos de calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4100, 'Playas', 'Puerto Rey', 'Playa de gran longitud y carácter urbano con total disponibilidad de equipamientos y servicios que hacen que cuente con un elevado grado de ocupación, sobre todo durante el periodo estival. Destaca el', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4902, 'Playas', 'Levante Almerimar', 'Playa ubicada en el corazón del núcleo turístico de Almerimar, que dispone de gran cantidad de servicios para el uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4902, 'Playas', 'Poniente Almerimar', 'Playa ubicada en el corazón del núcleo turístico de Almerimar, que dispone de gran cantidad de servicios para el uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4902, 'Playas', 'Balerma', 'Playa de tradición marinera, dotada con todo tipo de servicios e infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (4904, 'Playas', 'Balanegra', 'Se encuentra ubicada en una zona semiurbana donde abundan los invernaderos de plásticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7002, 'Playas', 'Cala''n Porter', 'Cala''n Porter es una playa equipada con los servicios típicos de una playa urbanizada y que acoge a gran cantidad de visitantes y residentes de la urbanización del mismo nombre.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7002, 'Playas', 'Son Bou', 'Es una de las playas más visitadas del sur de la isla, por la calidad de la arena, su gran extensión, la oferta turística que ofrece y su excelente equipamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7003, 'Playas', 'Alcudia', 'Posiblemente la playa más frecuentada de esta zona de la isla, de gran extensión, entorno agradable con vegetación de pinos, totalmente equipada y con arena y aguas de gran calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7003, 'Playas', 'Alcanada', 'Pequeña playa rodeada de vegetación, muy aconsejable para fondear los barcos y para la práctica de los deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7011, 'Playas', 'Magalluf', 'Playa muy conocida por el turismo que frecuenta la zona, ya que está totalmente equipada y dispone de gran oferta hotelera y de ocio en sus alrededores.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7011, 'Playas', 'Cala Fornells', 'Cala rodeada de vegetación con gran ocupación hotelera, donde pueden encontrarse embarcaciones turísticas de visión submarina.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7011, 'Playas', 'Peguera', 'Playa urbana que acoge gran cantidad del turismo de la zona y que dispone de instalaciones y servicios de todo tipo, así como una gran oferta de ocio en sus alrededores.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7013, 'Playas', 'Ses Estanques', 'Es la última playa del término municipal de Campos, lindando con el Hotel Marqués del Palmer y la playa del mismo nombre, con arena de tonalidades doradas y muy poca pendiente.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7013, 'Playas', 'S''Arenal de Sa Rápita', 'Es una de las tres playas ubicadas en la Ensenada de Sa Rápita, junto con la Playa de Ses Covetes y la Playa d''Es Trenc, una gran extensión de arena blanca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7013, 'Playas', 'Ses Covetes', 'Ses Covetes es la playa más pequeña de las tres que se encuentran en la Ensenada de Sa Rápita, intermedia entre las playas del S''Arenal de Sa Rápita y Es Trenc.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7014, 'Playas', 'Canyamel', 'Se trata de una playa con un buen equipamiento que presenta un elevado grado de ocupación durante el verano, sobre todo turismo extranjero.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7014, 'Playas', 'Sa Font de Sa Cala', 'Playa que, rodeada de vegetación, dispone de servicios e  infraestructuras y goza de un entorno muy agradable para el visitante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7014, 'Playas', 'Son Moll', 'Playa con buenas infraestructuras y servicios que confirman el alto grado de ocupación que presenta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7015, 'Playas', 'Son Xoriguer', 'Esta playa es conocida con el nombre de la urbanización cercana de Son Xoriguer, y presenta un alto grado de ocupación y una gran oferta de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7015, 'Playas', 'Cala''n Bosch', 'Cala muy cercana a la urbanización del mismo nombre y muy frecuentada por sus residentes, que disponen de alquiler de sombrillas, hamacas y una excelente calidad de arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7015, 'Playas', 'Cala Blanca', 'Cala muy turística que dispone de un buen equipamiento y que toma su nombre de la urbanización cercana, así como del color blanco de su excelente arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7019, 'Playas', 'Sa Calobra', 'Es de las pocas playas de esta zona a la que se puede llegar en coche, por lo que presenta un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7022, 'Playas', 'Cala Ferrera', 'Playa de entorno agradable, que dispone de instalaciones y servicios varios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7022, 'Playas', 'Cala Mitjana', 'Cala de carácter aislado, rodeada de vegetación mediterránea y poco frecuentada por el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7022, 'Playas', 'Cala Marçal', 'Cala muy tranquila, tanto su ambiente como sus cristalinas aguas, que dispone de infraestructuras y servicios para el uso del visitante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7023, 'Playas', 'Cala Galdana', 'Cala Galdana es quizá una de las playa más conocidas y visitadas de la isla, totalmente equipada y muy apropiada para disfrutarla en familia. Zona de pic-nic gratuita.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7026, 'Playas', 'Talamanca', 'Playa muy cercana a Ibiza, muy bien equipada y muy apreciada por el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7026, 'Playas', 'Es Vivé', 'Es Vivé toma su nombre de un antiguo vivero de langostas, es un sitio muy turístico y muy bien equipado para el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7026, 'Playas', 'Ses Figueretes', 'Playa urbana, ubicada en el mismo núcleo de Ibiza y con todos los servicios propios de una playa de ciudad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7031, 'Playas', 'El Arenal', 'Esta playa constituye el final de la extensa playa conocida con el mismo nombre de Playa del Arenal perteneciente al término vecino de Palma de Mallorca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7033, 'Playas', 'Caló Antena', 'Playa semiurbana de unos 40 metros de ancho y un fondo que llega a los 60 metros, de arena blanca y fina, con instalaciones desmontables.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7039, 'Playas', 'Muro', 'La Platja de Muro se presenta como una excelente playa de gran longitud con arena de buena calidad, servicios disponibles y poca profundidad, muy indicada para familias con niños y personas con alguna', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7040, 'Playas', 'Cala Major', 'Playa de carácter urbano situada en una de las zonas más turísticas de los alrededores de Palma de Mallorca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7040, 'Playas', 'C''an Pere Antoni', 'Playa situada en el núcleo urbano de Palma de Mallorca, rodeada de edificios y gran actividad marítima, por su cercanía a los diferentes puertos de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7040, 'Playas', 'Ciudad Jardín', 'Playa urbana muy frecuentada por un turismo familiar que dispone de buenos servicios y accesos, incluso para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7042, 'Playas', 'Platja d''Albercuix', 'Playa de arena ubicada en la Bahía de Pollença, con un alto grado de ocupación y totalmente equipada, incluso con acceso para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7046, 'Playas', 'Cala Salada', 'Playa de dimensiones moderadas y arena dorada situada frente a Sa Conillera.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7046, 'Playas', 'Cala Gració', 'Playa totalmente equipada que acoge a gran cantidad de turistas y vecinos de urbanizaciones próximas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7046, 'Playas', 'Caló des Moro', 'Playa urbana con instalaciones y servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7048, 'Playas', 'S''Estanyol', 'Playa urbana situada a dos kilómetros de Sant Antoni de Portmany, aunque pertenece al término de Sant Josep de Sa Talaia.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7048, 'Playas', 'Pinet', 'Muy frecuentada por visitantes y rodeada de edificaciones que albergan el turismo de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7048, 'Playas', 'Punta Xinxó', 'Pequeña playa cercana al núcleo de Sant Antoni de Portmany donde puede disfrutarse de alquileres de hamacas, sombrillas, etc.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7050, 'Playas', 'Cala San Vicente', 'Playa con todos los servicios y comodidades propias de un núcleo turístico. Ideal para turismo familiar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7050, 'Playas', 'Port de Benirrás', 'Playa en un paisaje excepcional. La roca Cavall Bernat preside imponente la entrada a la cala. Cuenta con acceso para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7051, 'Playas', 'Cala Moreia', 'Playa urbana rodeada de edificios de apartamentos que goza de los servicios típicos de una playa de ciudad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7051, 'Playas', 'Sa Coma', 'Playa bien equipada, muy aparente para disfrutarla con niños debido a la superficie llana de su arena y la poca pendiente que presenta.', 'verificado_manual', date('now'));

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7051, 'Playas', 'Cala Millor', 'Excepcional playa que dispone de todo tipo de instalaciones, servicios y rodeada de gran oferta turística, por lo que recibe una gran afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7052, 'Playas', 'Punta Prima', 'Excelente playa ubicada en la punta sureste de la isla de Menorca, que toma su nombre del núcleo urbano en el que se encuentra y que dispone de un total equipamiento en cuanto a servicios, instalacion', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7052, 'Playas', 'Binibeca Nou', 'Playa muy resguardada que goza de unas aguas muy tranquilas, tanto para el baño como para el fondeo de los barcos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7054, 'Playas', 'S''Argamassa', 'Playa de ambiente tranquilo en zona turístico-residencial, con pinos a pie de playa y predominio de fondos poco profundos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7055, 'Playas', 'Son Serra de Marina', 'Playa situada a lo largo de la urbanización del mismo nombre, muy frecuentada por sus residentes, aunque bastante escasa en servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7057, 'Playas', 'Sa Font de N''Alis', 'Playa rústica ubicada en el Parque Natural de Mondragó, muy apreciada por el turismo familiar de la zona debido a los servicios y a la tranquilidad que ofrece.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7061, 'Playas', 'Puerto de Sóller', 'Playa muy frecuentada por el turismo por estar situada muy cerca del puerto de Sóller, pintoresco núcleo urbano de la isla de Mallorca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7061, 'Playas', 'En Repic', 'Playa situada en la Ensenada del Puerto de Sóller, muy atractivo para el turismo de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7062, 'Playas', 'Cala Bona', 'Esta playa se caracteriza por estar dividida en tres partes con pequeños diques de piedra, y se encuentra ubicada en una urbanización del mismo nombre.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7902, 'Playas', 'Sant Tomas', 'Playa muy amplia que presenta un elevado grado de ocupación, dispone de un buen equipamiento y goza de un ambiente muy tranquilo para el visitante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (7902, 'Playas', 'Sant Adeodato', 'Playa muy cercana a la playa de Sant Tomas, con idénticas características en cuanto a su equipamiento y tranquilidad, desde donde se pueden ver una de las puestas de sol más bonitas de Menorca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8006, 'Playas', 'La Musclera', 'Playa en al que se protege la vegetación autóctona del litoral arenoso, mediante la delimitación de un espacio de protección de 1.500 m2 donde se pueden observar especies como el rave de mar, el passa', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8006, 'Playas', 'La Picordia', 'Playa protegida semiurbana sin paseo marítimo, que presenta unos alrededores algo descuidados. Principalmente compuesta por rocas y arena dorada. El estado habitual de la mar es aguas tranquilas. El n', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8006, 'Playas', 'El Cavaió', 'Playa dotada de gran cantidad de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8015, 'Playas', 'Platja de la Mora', 'Playa situada entre el límite de Sant Adrià y el Puerto', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8015, 'Playas', 'Platja del Coco', 'Playa localizada entre la Plaza dels Patins de Vela y la Calle Cervantes', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8015, 'Playas', 'Platja del Pont de Petroli', 'Playa ubicada entre la Avenida de Sant Ignasi de Loiola y la Plaza de los Patines de Vela', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8019, 'Playas', 'Sant Sebastià', 'Esta playa dispone de todo tipo de infraestructuras, así como buenos accesos adaptados para personas con alguna discapacidad. Se encuentra ubicada muy cerca de la dársena industrial y los muelles rela', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8019, 'Playas', 'La Barceloneta', 'Playa de Barcelona por excelencia que toma su nombre del antiguo barrio marinero, La Barceloneta, y dispone de todos los servicios propios de una playa urbana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8019, 'Playas', 'La Nova Icària', 'La Playa de la Nova Icària presenta un alto grado de ocupación y está ubicada junto al Puerto Olímpico de Barcelona, separada de las playas colindantes por pequeños espigones, enlazándose con el paseo', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8029, 'Playas', 'Cabrera', 'La Playa de Cabrera, junto con la Playa de Poniente, son las dos playas de  mayor longitud del término municipal. Presentan un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8032, 'Playas', 'Els Tres Micos', 'La Platja dels Tres Micos se localiza frente a una urbanización de viviendas unifamiliares en un entorno muy arbolado y agradable, estando muy bien equipada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8032, 'Playas', 'Platja del Bassiot', 'Playa muy cuidada que disfruta del encanto que le otorgan las barcas de los pescadores concentradas en uno de sus extremos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8035, 'Playas', 'Les Roques', 'Playa formada por varias calitas con grandes rocas desde donde puede practicarse la pesca con caña.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8035, 'Playas', 'Garbí', 'La Playa de Garbí constituye una continuación de la Playa Grande de Calella de Mar, por lo que goza de los servicios e infraestructuras de la playa vecina, pero resulta algo más tranquila y recomendab', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8035, 'Playas', 'Platja Gran', 'Es la playa más concurrida de la zona, con gran cantidad de oferta hotelera, multitud de infraestructuras y servicios playeros que atraen mucho turismo, sobre todo extranjero', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8040, 'Playas', 'Canet de Mar', 'Playa de gran extensión muy frecuentada por turistas, con un gran paseo marítimo con palmeras muy frecuentado durante la época estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8056, 'Playas', 'Castelldefels', 'La Playa de Castelldefels es una playa muy bien equipada, con mucho ambiente juvenil, que alberga un Club Náutico y varias escuelas de vela para la práctica de cualquier deporte relacionado con el vie', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8074, 'Playas', 'Mota de Sant Pere', 'Playa ubicada en una zona industrial, en construcción,  donde se encuentran más aficionados a la caña que bañistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8074, 'Playas', 'Cubelles', 'La Playa de Cubelles es una de las más frecuentadas de toda una serie de pequeñas playas separadas por espigones de piedras, comunicadas todas por un paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8074, 'Playas', 'Platja de les Salines', 'La playa Platja de les Salines, situada en Cubelles, es una playa de arena de 450 metros de longitud. Cuenta con servicios básicos como aseos y aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8089, 'Playas', 'Gavà', 'Extensa playa de arena dorada, que dispone de los servicios más esenciales para el uso del público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8110, 'Playas', 'Malgrat Centre', 'Playa urbana de gran extensión, con buenos servicios, pero su cercanía a las vías del tren le resta calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8110, 'Playas', 'Malgrat de la Conca', 'Playa que goza de unas características inmejorables para practicar el vuelo de la cometa, el Wind-Surf y cualquier otro deporte de vela.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8118, 'Playas', 'Platja del Masnou', 'La playa del Masnou se conoce como el rincón de los surfistas de esta zona. Dispone de una gran explanada para aparcar el coche, donde se ubica el acceso a la playa a través de un paso subterráneo. Di', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8118, 'Playas', 'Ocata', 'La Playa de Ocata, de gran extensión y anchura, es una buena playa ubicada en pleno casco urbano del municipio y que cuenta, además, con una zona acondicionada para distintos deportes, con un Club Náu', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8121, 'Playas', 'El Varador', 'La Playa del Varador es una de las más urbanas y frecuentadas de Mataró ya que posee unos servicios e infraestructuras que la hacen inmejorable para su uso, sobre todo para las familias con niños.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8121, 'Playas', 'El Callao', 'Pequeña playa de calidad,continuación de la Playa del Varador', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8121, 'Playas', 'Sant Simó', 'Playa de gran extensión y carácter urbano, muy frecuentada en uno de sus extremos, al contrario que en el otro, conocido como El Fortí, al no disponer de buenos accesos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8126, 'Playas', 'Les Moreres', 'Pequeña playa de arena dorada', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8126, 'Playas', 'Sant Joan', 'Playa de arena dorada y aguas tranquilas', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8126, 'Playas', 'Pla de Montgat', 'Playa de arena dorada y oleaje moderado', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8163, 'Playas', 'Playa del Pins', 'Extensa playa que, aunque presenta un elevado grado de ocupación, resulta mucho más tranquila que las playas de alrededor y dispone del mismo equipamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8163, 'Playas', 'Playa dels Pescadors', 'La playa Playa de los Pescadores, situada en Pineda de Mar, es una playa de arena de 1100 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8163, 'Playas', 'Playa de La Riera', 'La Playa de La Riera, situada en Pineda de Mar, es una playa de arena de 580 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8169, 'Playas', 'Platja Equipada', 'Playa de arena dorada y oscura', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8172, 'Playas', 'Bellamar', 'La Playa de Bellamar, junto al Club Náutico de Premià de Mar, se corresponde con el primer tramo de un largo arenal dividido en varias zonas, siendo éste el más resguardado por uno de los espigones de', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8172, 'Playas', 'Platja de Llevant', 'Playa de arena a la que se accede a través de un paso subterráneo que salva las vías del tren y la carretera, muy cercanas a la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8172, 'Playas', 'Platja de Ponent', 'Esta playa constituye un pequeño paraíso para los que quieren disfrutar de la práctica del surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8194, 'Playas', 'Platja del Litoral', 'Esta gran playa se encuentra entre la Central Térmica y el río Besós.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8194, 'Playas', 'El Fórum', 'La playa El Fórum, situada en Sant Adrià de Besòs, es una playa de arena de 460 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8197, 'Playas', 'L''Estació', 'Playa de reducidas dimensiones ubicada bajo la Estación de tren de Sant Andreu de Llavaneres y frecuentada generalmente por los residentes de la zona, más que por los turistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8197, 'Playas', 'Les Barques', 'Pequeña playa aneja a la Playa de Sant Andreu de Llavaneres, a la que se puede llegar andando, y muy cercana a las vías del tren.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8219, 'Playas', 'Platja de Ponent', 'Es una de las playas más largas del término de Vilassar de Mar, junto con la Playa de Cabrera, ambas de carácter urbano y con unas condiciones tranquilas para el baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8219, 'Playas', 'L''Astillero', 'Playa de carácter urbano compuesta de rocas y arena, que se localiza en el mismo casco urbano de Vilassar de Mar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8219, 'Playas', 'L''Almadrava', 'La Playa de La Almadraba es una playa urbana de pequeña extensión localizada en el mismo casco urbano de Vilassar de Mar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8235, 'Playas', 'Roques Blanques', 'Playa de aspecto rústico debido a la existencia de un macizo rocoso. Muy cercana a la carretera N-II y a la vía del tren. Se encuentra poco equipada de servicios e infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8235, 'Playas', 'La Murtra', 'Playa de arena y carácter aislado que dispone de servicios de alquiler de sombrillas y hamacas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8235, 'Playas', 'Can Villar', 'Esta playa se encuentra cerca del pueblo de Sant Pol de Mar y ofrece unas bonitas vistas del casco urbano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8261, 'Playas', 'Platja de les Dunes', 'Se extiende a lo largo de toda su línea de costa, resultando muy amplia, cómoda y con gran cantidad de servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8261, 'Playas', 'Platja de Llevant', 'La playa Platja de Llevant, situada en Santa Susanna, es una playa de arena de 815 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8261, 'Playas', 'Platja de les “Caletes”', 'La playa Platja de les Caletes, situada en Santa Susanna, es una playa de arena de 445 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8264, 'Playas', 'Sant Vicenç de Montalt', 'Playa muy ancha localizada junto al Puerto de Balís que dispone de gran cantidad de servicios de calidad que le dan un buen ambiente, y que por otra parte es un buen ejemplo de limpieza.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8270, 'Playas', 'Platja de L''Home Mort', 'Playa que se une a la Playa de Roses y está rodeada de acantilados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8270, 'Playas', 'Platja de la Desenrocada', 'Playa ubicada en un entorno natural, de carácter aislada, sin ningún tipo de servicios e infraestructuras para el público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8270, 'Playas', 'Les Coves', 'Playa estrecha', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8301, 'Playas', 'Platja de la Murtra', 'Playa de baja afluencia', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8307, 'Playas', 'Platja Llarga d''Ibersol', 'Playa en forma de ensenada, con pequeños espigones de piedras y con una excelente arena dorada. Está situada entre el término municipal de Cubelles y antes de la playa de Sant Gervasi. Un 60% de esta ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8307, 'Playas', 'Sant Gervasi', 'Playa protegida con diques de piedras a ambos lados, lo que le dota de unas tranquilas aguas para el baño, y con poca profundidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (8307, 'Playas', 'Ribes Roges', 'Playa dotada con gran cantidad de servicios e infraestructuras, indicada para los niños debido a la tranquilidad de sus aguas y poca profundidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11004, 'Playas', 'El Rinconcillo', 'Se trata de la playa más grande de Algeciras. Su gran longitud y la disponibilidad de equipamientos y servicios la convierten en la playa más visitada por los habitantes de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11004, 'Playas', 'Getares', 'Playa rodeada de montañas con mucha vegetación, que toma su nombre de la urbanización en la que se encuentra, y que cuenta con varios servicios que la hacen muy cómoda para su uso.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11007, 'Playas', 'Caños de Meca', 'La Playa del Faro de Trafalgar,  situada dentro del entorno de "Caños de Meca", cuenta con una extensa franja de arena dorada y aguas muy claras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11007, 'Playas', 'El Carmen', 'Playa urbana situada al lado del Puerto de Barbate, con un gran paseo marítimo y muy bien equipada, donde se practica el Wind-Surf y la pesca con caña.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11008, 'Playas', 'Palmones', 'Playa muy cercana a Algeciras rodeada de un entorno industrial que le resta atractivo. Paseo marítimo transversal a la playa, a lo largo de la desembocadura del río', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11012, 'Playas', 'La Victoria', 'Es el arenal de Cádiz por excelencia, siendo una playa muy concurrida por todos los servicios con que cuentan los bañistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11012, 'Playas', 'Santa María del Mar', 'Santa María del Mar es la playa más pequeña y recogida de todas a la que se accede por rampas o por las escaleras en forma de caracol que separan esta playa de la Playa de la Victoria.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11012, 'Playas', 'Cortadura', 'Playa muy próxima a la autovía a las afueras de Cádiz, en la que se forman unas dunas características con una excelente superficie de arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11014, 'Playas', 'Cala del Aceite', 'Cala de arena fina y aguas turquesas resguardada del viento de la zona por unos acantilados y a la que se accede mediante unas escalerillas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11014, 'Playas', 'Calas del Quinto y Camacho', 'Las conocidas como Calas del Quinto son tres calas de reducido tamaño denominadas Cala Melchor, Cala Pitones y Cala Sudario, todas ellas en medio de un entorno natural y bordeadas por cortados de tier', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11015, 'Playas', 'El Puerco', 'Es la continuación de la Playa de la Barrosa, aunque en este caso apenas cuenta con servicios. Está resguardada por pequeños acantilados con escaleras de acceso a la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11015, 'Playas', 'La Barrosa', 'Playa urbanizada y muy frecuentada, aunque recomendable por resultar muy cómoda por la amplitud y variedad de servicios disponibles, así como por la calidad de su arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11015, 'Playas', 'Sancti-Petri', 'Fantástica playa para la práctica del Wind-Surf, sobre todo cerca del puerto pesquero, donde se forman espectaculares corrientes de viento entre esta playa y la del Castillo. En la zona residencial es', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11016, 'Playas', 'Camarón', 'Playa de arena con gran cantidad de servicios e instalaciones disponibles para su uso público, y en la que se practican todo tipo de deportes: Wind-Surf, vela, golf, footing...', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11016, 'Playas', 'Cruz del Mar', 'Playa muy visitada con todo tipo de servicios localizada en la parte sur del Puerto de Chipiona, lugar en el que se encuentran los típicos corrales de pesca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11016, 'Playas', 'De Regla', 'Playa cosmopolita ubicada en pleno centro urbano de Chipiona junto al Monasterio de Nuestra Señora de Regla, con una gran oferta para el ocio', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11022, 'Playas', 'El Burgo', 'Esta playa se caracteriza por su gran dimensión y arena gris, siendo una zona tranquila.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11022, 'Playas', 'La Atunara', 'Actualmente esta playa se conoce con el nombre de Sobrevela. Playa de oscura arena que alberga un Puerto Pesquero que recibe el mismo nombre.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11022, 'Playas', 'La Atunara', 'Playa situada entre la Playa de Santa Bárbara y la Playa de la Atunara, con poco atractivo turístico, pero bien equipada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11027, 'Playas', 'Fuentebravía', 'Esta playa se encuentra ubicada en una zona residencial de la cual toma su nombre, y que presenta un alto grado de ocupación. En ella puede practicarse el submarinismo, la pesca y el Wind-Surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11027, 'Playas', 'La Muralla', 'Se trata de una cala arenosa encajada entre acantilados, en las inmediaciones del Castillo de Santa Catalina, que la separa de la playa de La Calita.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11027, 'Playas', 'La Puntilla', 'Playa ubicada en la desembocadura del Río Guadalete y separada de éste por un espigón, donde puede disfrutarse de unas aguas tranquilas para el baño, aunque resulta algo ventosa. Excelente para volar ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11028, 'Playas', 'La Cachucha', 'Playa de arena dorada, situada en el núcleo urbano de Puerto Real, en la misma Bahía de Cádiz.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11028, 'Playas', 'La Ministra', 'Playa familiar de la barriada de Río San Pedro', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11030, 'Playas', 'El Rompidillo', 'Playa urbana localizada entre el Puerto de Rota y el Puerto Militar, donde sopla un fuerte viento, por lo que resulta muy interesante para los aficionados al Wind-Surf y a la vela.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11030, 'Playas', 'La Ballena', 'Playa de arena de gran extensión que dispone de una gran cantidad de servicios e instalaciones, así como de alquiler de hamacas, sombrillas, o incluso de embarcaciones náuticas. El extremo norte de es', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11031, 'Playas', 'Camposoto', 'Playa rústica ubicada en un entorno plano y semisalvaje donde el viento sopla con intensidad y a la que se llega en coche atravesando las marismas. Está dividida en dos tramos: Camposoto, con más serv', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11032, 'Playas', 'Bajo de Guía', 'La Playa Bajo de Guía de arena fina y dorada resulta excelente para la práctica de la vela o cualquier otro deporte relacionado con el viento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11032, 'Playas', 'La Calzada', 'La Playa de La Calzada es una playa muy ancha, donde se realizan las famosas carreras de caballos organizadas todos los veranos, por lo que también se la conoce como El Hipódromo. También se encuentra', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11032, 'Playas', 'La Jara', 'La Playa de la Jara se encuentra protegida por unos macizos rocosos que la convierten en una playa muy tranquila donde resulta fácil la navegación de embarcaciones de recreo.', 'verificado_manual', date('now'));

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11033, 'Playas', 'La Alcaidesa', 'A esta playa se accede desde la urbanización de La Alcaidesa, y dispone de todos los servicios que le proporciona la misma urbanización, incluido un gran campo de golf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11033, 'Playas', 'Campamento', 'Playa ubicada entre las barriadas de Campamento y  Puente Mayorga, a las afueras de Algeciras. Cuenta con aseos, teléfono, papeleras, sillas anfibias para discapacitados y servicio de limpieza diaria.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11035, 'Playas', 'Atlanterra', 'Es la continuación de la Playa de Zahara de los Atunes. Toma el nombre de una urbanización cercana de casas unifamiliares en el Cabo de la Plata . Dispone de todos los servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11035, 'Playas', 'Bolonia', 'Esta playa salvaje de arena blanca esta considerada como el paraíso del Wind-Surf por el fuerte viento que reina. Protegida por la Junta de Andalucía.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (11039, 'Playas', 'El Palmar', 'Playa kilométrica donde puede disfrutarse de una gran tranquilidad alterada únicamente por el viento de la zona, ideal para practicar el Wind-Surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12004, 'Playas', 'Mañetes', 'Playa de excelente características que tiene un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12009, 'Playas', 'Ben Afeli', 'Playa de carácter urbano ubicada al sur del Puerto de Castellón, de poca extensión.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12009, 'Playas', 'La Torre', 'Playa de grava y arena ubicada al norte de la desembocadura del Riu Millars.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12011, 'Playas', 'Playa Casablanca', 'La Playa de Casablanca está localizada en el límite del término provincial de Castellón y Valencia, en una zona urbanizada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12027, 'Playas', 'Gurugú', 'Playa de arena y grava, con carácter urbano que presenta un grado medio de ocupación durante la época de verano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12027, 'Playas', 'Morrongo', 'Playa urbana totalmente acondicionada para su uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12027, 'Playas', 'Mar Xica', 'Extensa playa de grava ubicada al norte del casco urbano de Benicarló que no goza de gran afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12028, 'Playas', 'Playa Heliópolis', 'Playa con servicios y equipamientos de calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12028, 'Playas', 'Els Terrers', 'Playa con servicios y equipamientos de excelente calidad', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12028, 'Playas', 'Torre Sant Vicent', 'Playa que cuenta con servicios y equipamientos de calidad y con un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12032, 'Playas', 'L''Arenal', 'Playa ubicada al norte del Puerto de Burriana, con gran afluencia de público y todo tipo de equipamientos y alquileres náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12032, 'Playas', 'Grao - Malvarrosa', 'Playa ubicada al norte de la Playa del Arenal, con gran afluencia de público', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12033, 'Playas', 'Torre de la Sal', 'Playa localizada en una zona residencial, apta para la práctica de todo tipo de deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12040, 'Playas', 'El Pinar', 'Esta playa se encuentra ubicada junto al Puerto de Castellón, de carácter urbano, y con un alto grado de ocupación y equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12040, 'Playas', 'El Gurugú', 'Playa semiurbana con una gran anchura de arena a lo largo de un kilómetro de longitud que dispone de todo tipo de servicios para su uso.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12040, 'Playas', 'El Serradal', 'Es una playa del término de Castellón aunque se encuentra ubicada más cerca de Benicasim, en una zona semiurbana con poca afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12053, 'Playas', 'El Cerezo', 'La Playa del Cerezo es una de las que conforman las llamadas Playas de Chilches, de carácter semiurbano y de gran extensión.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12053, 'Playas', 'Les Cases', 'Playa urbana de grava y arena, que dispone de variedad de servicios y equipamiento para personas con movilidad reducida', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12074, 'Playas', 'Playa de La Llosa', 'Playa aislada sin ningún tipo de equipamiento ni servicios esenciales para su uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12077, 'Playas', 'Masbo', 'La Playa de Masbo, junto con la Platja del Grau, son las más concurridas de Moncófar, ubicadas en zonas urbanas y con variedad de equipamientos', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12077, 'Playas', 'El Grau', 'La Platja del Grau, junto con la Playa del Masbo, son las más concurridas de Moncófar, ubicadas en zonas urbanas y con variedad de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12082, 'Playas', 'Playa de L''Alcudia', 'Playa compuesta por grava ubicada en zona medio urbanizada', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12082, 'Playas', 'Playa El Bovalar', 'Playa compuesta de grava ubicada en zona urbana. Con disponibilidad de servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12085, 'Playas', 'Platgetes de Bellver', 'Playa de carácter semiurbano, compuesta de grava y arena, con baja afluencia de público. A unas veintisiete millas se encuentra la Reserva Marina de las Islas Columbretes.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12085, 'Playas', 'Oropesa Vieja', 'Playa semiurbana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12117, 'Playas', 'Torrenostra', 'Playa totalmente equipada, incluso con accesos para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12117, 'Playas', 'Nord de Torreblanca', 'Playa con acceso adaptado para discapacitados y demás servicios públicos, ubicada en una zona urbana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12138, 'Playas', 'Cala Puntal', 'Playa de carácter urbano que dispone de los servicios más elementales para su uso.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (12138, 'Playas', 'Playa de les Salines', 'Playa con los servicios mínimos necesarios para el uso del público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15004, 'Playas', 'Ares', 'Es la playa del nucleo urbano de Ares, tranquila y bien equipada. Con numerosos accesos para personas con movilidad reducida.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15008, 'Playas', 'El Pedrido', 'Playa situada en la desembocadura del río Mandeo, sometida a las variaciones de la marea.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15008, 'Playas', 'Gandarío', 'Playa bien equipada y con gran afluencia de visitantes que practican diversas actividades deportivas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15011, 'Playas', 'Agramuiña', 'Playa de arena blanca situada en una zona urbana con bajo grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15011, 'Playas', 'Barraña', 'Playa con elevado índice de ocupación en época estival, con aguas limpias y tranquilas, con oferta de buenos servicios y cuidado arenal que se hace muy extenso en bajamar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15014, 'Playas', 'A Orixeira', 'Playa sometida a mucha variación en su anchura debido a la marea.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15014, 'Playas', 'Navaliños', 'Ubicada en una zona donde fondean pequeñas embarcaciones de pesca.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15015, 'Playas', 'La Madalena', 'Playa de gran calidad, tanto por sus características de agua, arena y amplitud como por sus instalaciones y servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15016, 'Playas', 'Camelle', 'Playa urbana que disfruta de aguas tranquilas para el baño pero considerada como playa ventosa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15016, 'Playas', 'Arou', 'Playa urbana con forma de media luna, aguas tranquilas, arena blanca y muy resguardada del viento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15019, 'Playas', 'Pedra do Sal', 'Playa de rocas y arena incluida en la Red Natura 2.000, como muchas playas de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15019, 'Playas', 'Baldaio', 'Extensa playa de arena ubicada dentro del entorno natural de Marismas de Baldaio.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15022, 'Playas', 'Area Longa', 'Playa con elevado grado de ocupación junto al puerto de Cedeira.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15022, 'Playas', 'A Magdalena', 'Playa urbana con un color de arena gris claro muy característico.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15023, 'Playas', 'Estorde', 'Esta playa se encuentra situada entre los términos municipales de Fisterra y Corcubión, al sur del término de Cée.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15023, 'Playas', 'A Concha', 'Playa urbana en forma de concha rodeada de avenidas del mismo núcleo de Cée.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15028, 'Playas', 'Quenxe', 'Playa urbana de Corcubión, con gran superficie de area blanca y aguas tranquilas, que dispone de todo tipo de servicios para el visitante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15028, 'Playas', 'Santa Isabel', 'Playa situada en pleno núcleo urbano de Corcubión con servicios para el visitante.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15028, 'Playas', 'Playa del Puerto', 'Playa portuaria de arena y fango que la pleamar cubre totalmente', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15030, 'Playas', 'Oza', 'La Playa de Lazareto está situada al sur del gran puerto de A Coruña, en uno de los extremos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15030, 'Playas', 'San Amaro', 'Muy cercana a Punta Herminia se ubica esta playa que registra un elevado grado de ocupación', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15030, 'Playas', 'As Lapas', 'Playa de arena de reducidas dimensiones que se encuentra en buen estado de conservación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15034, 'Playas', 'Ézaro', 'Única playa de este término municipal en la ensenada de Ezaro, donde desemboca el río Xallas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15035, 'Playas', 'Río Sandeu', 'Pertenece al término municipal de Fene, pero se encuentra muy cercana al núcleo urbano de Redes, término de Ares.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15036, 'Playas', 'Caranza', 'Playa artificial bien equipada muy frecuentada por el turismo de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15040, 'Playas', 'Laxe', 'Playa de gran belleza de arenas blancas y finas con una longitud de kilómetro y medio, y equipamientos propios de una playa urbana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15041, 'Playas', 'Caión', 'Arenal muy concurrido prácticamente dentro del pueblo de Caión, muy tranquila para el baño y con unas aguas muy limpias.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15044, 'Playas', 'Bares', 'Esta playa queda dividida en dos partes con la marea alta, una parte en la zona urbana y portuaria y la otra conocida como Iglesia Vella, con una extensa zona dunar y dividida a su vez por un saliente', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15044, 'Playas', 'Esteiro', 'Playa con fuerte oleaje en una zona y otra con aguas tranquilas en la desembocadura del río Esteiro, idónea para el baño de niños.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15048, 'Playas', 'Perbes', 'Playa muy visitada por el turismo de la zona que dispone de buen equipamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15051, 'Playas', 'Bestarruza', 'Única playa en este término municipal, junto al nucleo urbano de Mugardos. Playa artificial.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15052, 'Playas', 'O Coido', 'Está compuesta de rocas y arena, situada en la zona urbana de Muxia.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15052, 'Playas', 'A Cruz', 'Praia da Cruz está situada al norte del núcleo de Muxia, frecuentada por gente de la zona', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15058, 'Playas', 'Espiñeiro', 'Playa con alto grado de ocupación que dispone de los servicios más elementales para el uso del público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15058, 'Playas', 'Mera', 'Es la playa del núcleo urbano de Mera, muy visitada por residentes de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15061, 'Playas', 'Bimbieiro', 'En esta playa desemboca un pequeño riachuelo que hace variar su conformación. A continuación de la playa de Bimbieiro, al norte de la misma se encuentra una cala de piedras que se denomina Arxúa por l', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15062, 'Playas', 'Siavo', 'Playa de tamaño medio formada por arena y rocas que presenta un bajo grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15062, 'Playas', 'Broña', 'Situada en Punta Broña, de donde toma su nombre, con acondicionamientos de reciente construcción.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15067, 'Playas', 'Corna', 'Playa rodeada de un amplio campo dunar en el que crece vegetación propia de los ecosistemas costeros. Aguas limpias y tranquilas, con ausencia de fuertes vientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15067, 'Playas', 'A Illa', 'Presenta aguas limpias y tranquilas en ausencia de vientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15067, 'Playas', 'Lombiña', 'Playa con elevado nivel de ocupación en época estival debido a los buenos servicios que oferta, calidad excelente de sus aguas y arenas blancas y finas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15069, 'Playas', 'Ber', 'Muy frecuentada por gente de la zona por la buena calidad de conservación y servicios que ofrece.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15071, 'Playas', 'Rio Sieira', 'Casi un kilómetro de playa aislada compuesta de rocas y arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15072, 'Playas', 'A Torre', 'Playa con buen entorno, aguas tranquilas y bastante frecuentada por gente de la zona. Regenerada en 2008', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15072, 'Playas', 'O Pazo', 'Industrias conserveras y astilleros en sus inmediaciones. Regenerada en 2008.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15073, 'Playas', 'Ribeira Grande', 'Ribeira Grande y Ribeiriña son dos playas urbanas de muy pequeño tamaño al abrigo del espigón del puerto de Corrubedo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15075, 'Playas', 'Sada', 'Esta playa urbana ha sido ampliada de forma artificial, acondicionando un paseo marítimo con formas geométricas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15087, 'Playas', 'Villarrube', 'Gran extensión de arena de aguas tranquilas, salvo en los extremos de la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15087, 'Playas', 'Baleo', 'Playa con una longitud aproximada de cuatrocientos metros que presenta un grado alto de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (15901, 'Playas', 'Fornos', 'La playa de Fornos, por la calidad de sus aguas, arena y entorno, posiblemente sea una de las mejores playas de Galicia.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17013, 'Playas', 'Sa Tuna', 'Playa de carácter semiurbano que acoge gran cantidad de barquitas de los pescadores de la zona', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17013, 'Playas', 'Aiguafreda', 'Esta playa carece de arena y esta acondicionada para el amarre de los barcos deportivos que frecuentan la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17023, 'Playas', 'S''Abanell', 'Aunque se trata de una playa que dispone de un equipamiento completo, la cantidad de gente que acude a ella durante la época estival le resta atractivo a la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17023, 'Playas', 'Blanes', 'Playa regenerada, muy bien equipada y con gran afluencia de público durante el verano', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17032, 'Playas', 'Llané Gran y Petit', 'Playa urbana rodeada de las pintorescas casas del pueblo de Cadaqués, donde se agolpan gran cantidad de barcas sobre la superficie de grava y arena oscura.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17034, 'Playas', 'Comptat de Sant Jordi', 'Segunda playa del término municipal de Calonge, presenta un carácter aislado pero es muy frecuentada por la gente del lugar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17034, 'Playas', 'Ses Torretes', 'Playa semiurbana, de ambiente tranquilo que ofrece todo tipo de alquileres, hamacas, sombrillas y embarcaciones náuticas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17047, 'Playas', 'Empúriabrava', 'Playa totalmente equipada que acoge mucho turismo durante la época estival', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17047, 'Playas', 'La Rovina', 'Playa de carácter aislado, muy azotada por el viento, por lo que goza de excelentes características para la práctica del Wind-Surf y demás deportes relacionados con el viento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17048, 'Playas', 'Sa Conca', 'Excelente playa turística pero que guarda un entorno muy atractivo a pesar del alto grado de ocupación que presenta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17048, 'Playas', 'Platja d''Aro', 'Es la playa más conocida y turística del término municipal, totalmente equipada y muy concurrida', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17054, 'Playas', 'Dels Morts', 'Se trata de la playa de Colera más visitada, de piedras y arena gris oscura y rodeada de altos acantilados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17062, 'Playas', 'Riells', 'Es la playa más turística de L''Escala, con servicios de calidad y que cuenta con acceso para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17062, 'Playas', 'Port d''en Perris', 'Playa urbana compuesta de pequeñas piedras acondicionada de manera que forma parte del núcleo urbano en el que está ubicada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17062, 'Playas', 'La Platja', 'Playa ubicada en el casco urbano de L''Escala, con un alto grado de ocupación y con los servicios propios de una playa urbana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17092, 'Playas', 'Cau del Llop', 'Playa semiurbana de grava y arena oscura muy frecuentada, tanto por bañistas como por embarcaciones de recreo que fondean por la zona.', 'verificado_manual', date('now'));

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17092, 'Playas', 'La Farella', 'Playa con un alto grado de ocupación, de ambiente tranquilo y que presenta gran cantidad de rocas donde practicar la pesca y el buceo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17092, 'Playas', 'El Port', 'Playa ubicada en el puerto pesquero, compuesta de arena oscura con textura gruesa y ocupada principalmente por gente de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17095, 'Playas', 'Santa Cristina', 'Playa de arena de excelente calidad, muy bien equipada y que goza de unas aguas muy limpias donde puede practicarse el submarinismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17095, 'Playas', 'Sa Boadella', 'Playa de arena fina rodeada de rocas y vegetación', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17117, 'Playas', 'Llafranc', 'Playa urbana totalmente equipada, que presenta un alto grado de ocupación y muy recomendable para vacaciones familiares.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17117, 'Playas', 'Tamariu', 'Playa totalmente equipada con servicios e instalaciones de todo tipo, muy transitada durante le época estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17118, 'Playas', 'Gran de Palamós', 'Playa totalmente equipada, con un elevado grado de ocupación y que dispone de alquileres de cualquier tipo de embarcación náutica.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17118, 'Playas', 'Cala de Morro del Vedell', 'Playa visitada por aficionados a la pesca, tanto deportiva como submarina, más que por bañistas y turistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17124, 'Playas', 'Pals', 'Extensa playa de arena muy frecuentada por el turismo de la zona y sobre todo por los amantes de los deportes de vela.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17138, 'Playas', 'Portbou', 'Playa totalmente equipada, con acceso para discapacitados, donde es común la práctica de deportes de vela y el kayak, además de las inmersiones para disfrutar de los fondos rocosos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17140, 'Playas', 'El Pas', 'Playa de excelente calidad que registra un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17152, 'Playas', 'Santa Margarida', 'Playa muy concurrida y muy bien equipada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17152, 'Playas', 'Salatar', 'Playa turística rodeada de apartamentos y hoteles que dispone de todo tipo de servicios e infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17152, 'Playas', 'El Rastell', 'Excelente playa que dispone de todo tipo de servicios e infraestructuras y de un paseo marítimo rodeado de palmeras muy propicio para caminar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17160, 'Playas', 'Sant Feliu', 'Playa con marcado carácter turístico equipada con todo tipo de servicios e infraestructuras', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17160, 'Playas', 'Sant Pol', 'Playa totalmente equipada, ubicada en una bahía donde atracan gran cantidad de barcos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17178, 'Playas', 'Sant Pere Pescador', 'Extensa franja de arena fina muy recomendable para la práctica de todos los deportes relacionados con el viento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17181, 'Playas', 'Senyor Ramón', 'Bonita playa de arena donde acuden muchas embarcaciones para fondear.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17199, 'Playas', 'Mas Pinell', 'Playa de gran dimensión compuesta de arena gruesa, que dispone de accesos para discapacitados, un "chiringuito" en la misma playa y servicio de alquileres náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17199, 'Playas', 'L''Estartit', 'Playa urbana desde donde pueden verse las Islas Medes, Parque Natural Subacuático, muy interesante para la práctica del buceo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17199, 'Playas', 'Cala Montgó', 'Playa de titularidad compartida entre Torroella de Montgrí y L''Escala. Esta situada junto al Monte del Montgó, desde donde se observan los acantilados de alrededor y donde se puede disfrutar de unas c', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17202, 'Playas', 'Santa María de Llorell', 'Playa muy animada con bonitas vistas a la bahía, con mucha vegetación y que dispone de servicios e infraestructuras y de un club de deportes.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (17202, 'Playas', 'Cala d''En Carles', 'Cala está dentro del Camping Llevadó. Destaca por la transparencia de sus aguas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18017, 'Playas', 'La Herradura', 'Playa urbana de ambiente familiar. Está muy bien equipada y cuenta con un alto nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18093, 'Playas', 'Castell de Ferro', 'Playa extensa con defensas artificiales en algunos tramos. Tiene paseo marítimo y algunos servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18124, 'Playas', 'Cambriles', 'La playa pertenece a dos términos municipales: Gualchos-Castell de Ferro y Lújar. No es una playa excesivamente concurrida.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18140, 'Playas', 'Calahonda', 'Playa turística bien equipada junto a la zona urbanizada de Calahonda, con mucha afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18140, 'Playas', 'Carchuna', 'Playa muy extensa (3 Km), por lo que a pesar de tener bastante afluencia, ofrece un aspecto tranquilo. Está rodeada de cultivos intensivos de invernaderos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18162, 'Playas', 'La Mamola', 'La playa de La Mamola pertenece al termino municipal de Polopos. Tiene un paseo marítimo con múltiples servicios turísticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18170, 'Playas', 'Casarones', 'Pequeña playa de rocas y grava, muy estrecha, sin ningún tipo de equipamiento ni servicios, en una zona de invernaderos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18170, 'Playas', 'El Lance', 'Estrecha playa de arena oscura, junto a la carretera N-340. Tiene algunos equipamientos y servicios de hostelería.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18173, 'Playas', 'La Charca', 'Playa extensa y relativamente ancha, con ambiente familiar y buenos servicios. Cuenta con paseo marítimo, tras el que se asientan varias urbanizaciones y edificios asociados al turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18177, 'Playas', 'Los Yesos', 'Pequeña playa junto al núcleo urbano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18177, 'Playas', 'Melicena', 'Playa tranquila en el núcleo urbano de Melicena con algunos equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (18720, 'Playas', 'Torrenueva', 'Playa muy concurrida con buenos servicios. Tiene paseo marítimo y el frente litoral está ocupado por edificaciones altas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20036, 'Playas', 'Hondarribia', 'Playa situada al Sudeste del cabo de Higer y al Noroeste de la desembocadura de la ría del Bidasoa, favoreciendo su formación un espigón que discurre lateralmente de Norte a Sur.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20039, 'Playas', 'Malkorbe', 'Playa situada al Sudeste del monte de San Antón, entre las puntas de Mazoparria y Altzoko-Arria.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20039, 'Playas', 'Gaztetape', 'Playa situada al Suroeste del monte de San Antón, con buenas condiciones para la práctica del surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20056, 'Playas', 'Ondarbeltz', 'Playa de arena situada en la desembocadura de la ría del Deba (margen izquierda), entre el espigón existente y la punta de Arrilaban.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20056, 'Playas', 'Mutriku', 'Playa de arena situada al Norte del puerto de Mutriku, cuya configuración ha variado tras la realización de las obras de mejora del acceso marítimo al puerto de Mutriku.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20061, 'Playas', 'Antilla', 'Playa de arena situada al Este de la desembocadura de la ría de Oria.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20064, 'Playas', 'Alabortza', 'Pequeña cala de cantos rodados', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20069, 'Playas', 'La Zurriola', 'Playa situada al Este de la desembocadura de la ría del Urumea y cercana a la punta de Monpas. Es habitual en ella la práctica del surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20069, 'Playas', 'La Concha', 'Playa situada en la Bahía de la Concha, entre el puerto pesquero de San Sebastián y el pico del Loro, que la separa de la playa de Ondarreta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20069, 'Playas', 'Playa de la Isla', 'Pequeña playa situada en la isla de Santa Clara, en la bahía de la Concha.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20079, 'Playas', 'Zarautz', 'Extensa playa de arena situada entre la desembocadura de la regata de Iñurritza o San Pelayo y la punta de Iteico, próxima a la carretera de comunicación entre Zarautz y Getaria. En su zona oriental e', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20081, 'Playas', 'Santiago', 'Playa de arena situada al Este de la desembocadura de la ría del Urola. Pertenece a los términos municipales de Getaria y Zumaia.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (20081, 'Playas', 'Itzurun', 'Playa de arena situada entre las puntas de Marianton y Algorri. Desde un punto de vista geológico constituye un marco único para el estudio de la geometría de sus estratos y sus estructuras sedimentar', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21005, 'Playas', 'Matalascañas', 'Playa urbana con alto nivel de servicios, limítrofe con la playa del Espacio Natural de Doñana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21010, 'Playas', 'Isla Canela', 'Playa con buena dotación de servicios muy próxima a la desembocadura del río Guadiana', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21010, 'Playas', 'Punta del Moral', 'Playa con buena dotación de servicios y fácil accesibilidad', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21010, 'Playas', 'San Bruno', 'Amplia playa de fina arena dorada y aguas tranquilas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21021, 'Playas', 'Nuevo Portil', 'Playa bordeada por una duna de cierta altura y con agradables vistas de la flecha de El Rompido.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21021, 'Playas', 'San Miguel', 'Su principal atractivo es su pinar, que lleva directamente a una extensa playa de arenas blancas y finas. En ella encontrará un entorno natural, conjugado con todos los equipamientos necesarios para l', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21042, 'Playas', 'Urbasur', 'Playa bordeada por un bosque de pinos próxima a la urbanización URBASUR', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21042, 'Playas', 'Casita Azul', 'Playa bordeada por un bosque de pinos', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21042, 'Playas', 'Gaviota', 'Playa conformada recientemente al abrigo del dique portuario. Se accede a través de una pasarela elevada que cruza la gola.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21044, 'Playas', 'La Antilla', 'Playa urbana con buen nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21050, 'Playas', 'El Parador', 'Playa bordeada por acantilados arenosos de cierta altura. En sus proximidades está el Parador Nacional de Mazagón.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21055, 'Playas', 'Mazagón', 'Se trata de una playa que se desarrolla a lo largo del frente urbano de Mazagón. Hacia Levante del núcleo urbano continúa la playa en su estado natural, bordeado por un acantilado arenoso sobre el que', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21060, 'Playas', 'El Portil', 'Esta playa se encuentra muy cerca de la Laguna del Portil. Se extiende desde La Bota hasta el término municipal de Cartaya. Se trata de una playa con ambiente familiar y buenas vistas a la Flecha de E', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21060, 'Playas', 'La Bota', 'Extenso y ancho arenal que da paso a El Portil. Situada entre pinares y dunas, permite dar agradables paseos y admirar su bello entorno natural.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (21060, 'Playas', 'Punta Umbría', 'Amplia playa urbana, de gran calidad ambiental, sostenible y dotada de múltiples equipamientos y servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27005, 'Playas', 'San Miguel', 'Extensa playa de arena blanca y fina.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27005, 'Playas', 'As Pasadas', 'Playa de arena blanca y oleaje moderado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27005, 'Playas', 'Lóngara', 'Playa de finas arenas blancas muy usada por surfistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27013, 'Playas', 'Caosa', 'Playa de carácter urbano situada en el núcleo de San Ciprián.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27013, 'Playas', 'Cubelas', 'Playa urbana con gran afluencia y oleaje moderado', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27019, 'Playas', 'A Rapadoira', 'Playa urbana situada en el mismo núcleo de Foz, muy familiar por sus servicios y características.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27019, 'Playas', 'Llás', 'Playa semiurbana, con un interesante sistema dunar, muy frecuentada por gente de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27019, 'Playas', 'Peizás', 'Playa de arenas blancas y oleaje moderado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27025, 'Playas', 'Lago', 'Playa muy tranquila situada entre dos espigones', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27025, 'Playas', 'Morás', 'Playa semiurbana que limita con el puerto de Morás.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27051, 'Playas', 'Rocas Brancas', 'Playa cercana al faro de Ribadeo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27051, 'Playas', 'Xuncos', 'Playa de rocas y arena con bajo grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27064, 'Playas', 'Abrela', 'Playa con un gran sistema dunar pináceo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27064, 'Playas', 'San Román', 'Extensa playa de arena blanca con sistema dunar muy bien conservado y protegido que se encuentra en una zona rústica muy tranquila.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27066, 'Playas', 'Area', 'Extensa playa muy frecuentada por el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27066, 'Playas', 'Covas', 'Playa urbana que goza de instalaciones y servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27902, 'Playas', 'O Cantiño', 'Playa muy frecuentada por el turismo de la zona.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (27902, 'Playas', 'O Portelo', 'Es la playa de Burela por excelencia, ubicada en pleno casco urbano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29005, 'Playas', 'Algarrobo', 'Playa de grava y arena con alto grado de ocupación, en una zona urbanizada con edificios altos. Posee buenos equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29005, 'Playas', 'Mezquitilla', 'Junto con la playa de Algarrobo, forma el frente litoral conocido como Algarrobo-Costa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29025, 'Playas', 'Malapesquera', 'Playa familiar, con alto nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29025, 'Playas', 'Santa Ana', 'Enclavada en el entorno del Cabo Busto conforma un paisaje de interés. Presenta alta afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29041, 'Playas', 'La Paloma', 'Preciosa playa de aguas tranquilas y gran afluencia de público. Dotada de un buen número de servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29041, 'Playas', 'Playa Ancha', 'Preciosa y cuidada playa de más de un kilómetro de longitud, con aguas tranquilas y gran afluencia de público. Dotada con un buen número de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29051, 'Playas', 'Arroyo de las Cañas', 'La playa se extiende desde el río Velerín hasta el arroyo de las Cañas. Presenta una afluencia de público moderada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29051, 'Playas', 'Arroyo Vaquero', 'Zona litoral con diversas urbanizaciones.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29054, 'Playas', 'Castillo', 'Situada antes de cruzar el río Fuengirola, junto al castillo de Sohail, forma parte del gran arenal de Fuengirola.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29054, 'Playas', 'Boliches-Las Gaviotas', 'Playa en el centro urbano muy popular, bien equipada, con buen nivel de servicios y alta ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29054, 'Playas', 'Fuengirola', 'Playa con buen nivel de servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29067, 'Playas', 'Baños del Carmen', 'Se trata de una estrecha franja que bordea un antiguo balneario. Los tramos de playa se situan a levante y poniente del balneario.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29067, 'Playas', 'Playa del Campo de Golf', 'Playa cercana al Club de Golf de Málaga y al aeropuerto.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29067, 'Playas', 'El Candado', 'Pequeña playa junto al Puerto Deportivo de El Candado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29068, 'Playas', 'Punta Chullera', 'Formación rocosa de especial interés paisajístico y riqueza ecológica, con aguas limpias indicadas para la pesca submarina.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29068, 'Playas', 'La Duquesa', 'Playa contigua al Puerto Deportivo de La Duquesa, se ha visto afectada por la regresión inducida por el puerto.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29069, 'Playas', 'La Venus', 'Playa situada en el casco urbano de Marbella, junto al río Represa. Presenta buenos servicios y alta ocupación. Una zona de la misma presenta fondo rocoso.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29069, 'Playas', 'Las Cañas', 'Estrecha franja de arena, entre los arroyos Las Cañas y Artola, de apenas 6 m. de ancho (incluso con zonas sin playa seca) y 1 Km. de largo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29069, 'Playas', 'Calahonda', 'Ultima playa del oeste de Marbella entre el Puerto de Cabopino y el límite con Mijas. Playa estrecha con fondos rocosos.', 'verificado_manual', date('now'));

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29070, 'Playas', 'Calahonda', 'Franja costera situada en el parte oeste del término municipal. Se trata de un estrecho y sinuoso borde litoral de arena y rocas, en una zona muy urbanizada al sur de la CN-340, que incluye calas dife', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29070, 'Playas', 'El Charcón', 'Playa con zonas de fondo rocoso situada en una zona poco urbanizada al este del término municipal.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29070, 'Playas', 'Las Doradas', 'Estrecha franja de arena y fondo rocoso en una zona con volumen de edificabilidad bajo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29075, 'Playas', 'Burriana', 'Playa muy frecuentada, de ambiente familiar. Entorno pintoresco y alto nivel de servicios y equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29082, 'Playas', 'Cala del Moral', 'Playa familiar muy concurrida, con todo tipo de servicios. La zona está muy urbanizada y cuenta con paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29082, 'Playas', 'Los Rubios', 'Playa situada en el barrio de Los Judíos. Junto con la playa de El Rincón de la Victoria y la de Torre de Benagalbón, abarcan todo el litoral del término municipal.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29082, 'Playas', 'Rincón de la Victoria', 'Extensa playa en la zona urbana de El Rincón de la Victoria. Ofrece todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29091, 'Playas', 'El Cenicero', 'Playa situada en la zona del Morche, que ofrece numerosos servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29091, 'Playas', 'El Morche', 'Playa urbanizada con buenos equipamientos. Cuenta con paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29094, 'Playas', 'Almayate', 'Playa muy extensa en una zona muy poco urbanizada. Apenas ofrece servicios y es muy poco frecuentada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29094, 'Playas', 'Benajarafe', 'Junto con la playa de Valle Niza, forma una extensa playa de arena oscura. En general no tiene buenos equipamientos, excepto en las zonas donde se asientan las urbanizaciones próximas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29094, 'Playas', 'Chilches', 'Playa muy extensa y muy estrecha en algunos tramos, junto a la carretera N-340. Existen varias urbanizaciones en la zona, de donde procede la mayoría de los usuarios de la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29901, 'Playas', 'El Bajondillo', 'Playa con un alto nivel de servicios, ambiente familiar y muy frecuentada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29901, 'Playas', 'La Carihuela', 'Playa con un alto nivel de servicios, ambiente familiar y muy frecuentada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (29901, 'Playas', 'Los Álamos', 'Playa familiar. Es la más alejada del centro de Torremolinos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30003, 'Playas', 'La Carolina', 'Pequeña playa aislada, pero con un alto grado de ocupación. Fácil acceso debido a una carretera cercana. Playa ancha y larga, existen restos de escollera de antiguos cocederos de esparto', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30016, 'Playas', 'Cala Fría', 'Cala de arena dorada rodeada de rocas, que conforman un entorno agradable. Aguas limpias idóneas para bucear. Escasos equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30016, 'Playas', 'Amoladeras', 'Playa de La Manga del Mar Mediterráneo urbana de arena dorada. Una parte de ella es un Espacio Natural Protegido. Ofrece algunos servicios: lavapies y aseos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30024, 'Playas', 'Calnegre', 'Playa ancha de arena fina dorada. Aunque presenta un grado medio de ocupación, se puede disfrutar en ella de un ambiente tranquilo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30035, 'Playas', 'Pudrimel', 'Playa de La Manga del Mar Mediterráneo semiurbana, con un grado medio de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30036, 'Playas', 'Las Salinas (Playas de la Llana)', 'Playa situada dentro del Parque Regional Salinas de San Pedro.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30041, 'Playas', 'Lastre', 'Playa con mucha afluencia estable, con servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30902, 'Playas', 'La Concha', 'Playa del Mar Menor muy agradable, de arena fina, pendiente suave y aguas cálidas', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30902, 'Playas', 'Carrión', 'Playa del Mar Menor, urbana con ambiente familiar. Ofrece unas aguas tranquilas y cálidas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (30902, 'Playas', 'Manzanares', 'Playa del Mar Menor, con un alto grado de ocupación, de aguas tranquilas y cálidas y pendiente suave', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33013, 'Playas', 'Arenal de Morís', 'Extensa playa en forma de concha y de arena dorada. Muy turística y concurrida, ofrece un buen nivel de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33013, 'Playas', 'El Viso', 'Playa enclavada dentro de los extensos arenales del concejo de Caravia.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33014, 'Playas', 'Candás', 'Enclavada junto al puerto de Candás, es una playa dotada con toda la oferta hostelera necesaria y con gran afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33014, 'Playas', 'Carranques 1 y 2', 'Playa ubicada en un entorno paisajístico de interés con calas, cuevas y abundante vegetación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33014, 'Playas', 'La Palmera', 'Es la playa del turístico pueblo de Candás. Disfruta de arena fina y ofrece todo tipo de equipamientos y la posibilidad de realizar diferentes deportes acuáticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33016, 'Playas', 'Arnao', 'Enclavada en una hondonada y resguardada, es una playa de arena y bolos dotada con buenos servicios y muy frecuentada por el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33016, 'Playas', 'Bahínas', 'Bonita playa semiurbana de arena oscura, bolos y oleaje moderado. Próxima a la localidad de Santa María del Mar. Ofrece un nivel aceptable de servicios y un grado medio de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33017, 'Playas', 'Arnao', 'Bonita playa de arena blanca y fina, y aguas tranquilas para el baño. Se encuentra enclavada en un bonito entorno, muy próxima al área recreativa de Arnao.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33018, 'Playas', 'Arnelles', 'Playa situada cerca del Puerto de Ortiguera que cuenta con algunos servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33019, 'Playas', 'La Espasa', 'Situada en la desembocadura del río Espasa, que divide los concejos de Caravia (derecha) y Colunga (izquierda). Playa extensa que está compuesta por arena dorada y ofrece un buen nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33019, 'Playas', 'La Griega', 'Extensa formación de arena dorada, en la que desemboca el río Libardón. Presenta fuerte oleaje, ocupación media y un buen nivel de equipamientos. Como dato curioso, se pueden ver en ella huellas fosil', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33019, 'Playas', 'La Isla', 'Playa urbana de arena dorada enfrente de la cual se sitúa el islote del que recibe su nombre. Dispone de paseo marítimo y buenos equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33023, 'Playas', 'Porcía', 'Playa con forma triangular con alta ocupación y que posee marismas y dunas de pequeña extensión, así como zonas arboladas', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33024, 'Playas', 'Arbeyal', 'Arenal de gran afluencia desde su regeneración en 1995. Bañado por aguas tranquilas, dispone de buenos servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33024, 'Playas', 'Cervigón', 'Playa colindante con la de San Lorenzo en la ciudad de Gijón. Denota una alta afluencia de público y dispone de bastantes equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33025, 'Playas', 'San Pedro de Antromero', 'Playa de gran valor geológico e interesante por los restos fósiles de huellas de dinosaurios que aparecen en ella.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33025, 'Playas', 'Aramar', 'Formada por bolos y rocas, esta playa situada en una ensenada cerrada por islotes', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33034, 'Playas', 'Cadavedo', 'Playa de tipo rural, en forma de concha, con un alto grado de ocupación en la época estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33036, 'Playas', 'Andrín', 'Formidable playa situada en un entorno impresionante rodeada de acantilados, en la que es conveniente tener cuidado debido al fuerte oleaje y a las corrientes que se forman en ella.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33036, 'Playas', 'Barro', 'Queda unida en bajamar a la playa de Sorraos. Disfruta de arena blanca, aguas cristalinas y un buen nivel de equipamientos', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33039, 'Playas', 'Aguilar', 'Extenso arenal de gran interés turístico que la convierte en una playa muy concurrida. Ofrece un buen nivel de equipamientos y una variada oferta hostelera.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33041, 'Playas', 'Frejulfe', 'Extenso arenal en el que existe un sistema dunar, cercano a la villa pesquera de Puerto de Vega. Presenta un fuerte oleaje, siendo la parte derecha la más apta para el baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33055, 'Playas', 'La Franca', 'Situada en la desembocadura del río Cabra, cuenta con arena fina blanca, gran afluencia de público y un buen nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33056, 'Playas', 'La Atalaya', 'Cala de reducidas dimensiones adyacente al puerto de Ribadesella. Se accede fácilmente a pie desde el casco urbano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33069, 'Playas', 'Los Quebrantos', 'Extensa playa de arena oscura unida al Playón de Bayas, en cuya zona occidental desemboca el río Nalón. Ofrece un nivel alto de servicios y tiene una gran afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33070, 'Playas', 'Peñarronda', 'Amplio arenal con una roca en el centro que da nombre a la playa. Los aficionados al surf, suelen frecuentar esta playa desde donde se pueden tomar buenas olas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33070, 'Playas', 'El Murallón', 'Pequeña playa situada en un bello entorno. Cuenta con buenos servicios, algunos de ellos compartidos con la playa Grande con la que limita al sur, y alta ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33076, 'Playas', 'Merón', 'Pequeña playa con forma de concha formada por arena y grava.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33076, 'Playas', 'Misiego', 'Está situada en la ría de Villaviciosa, por lo que disfruta de aguas tranquilas y arena dorada. No dispone apenas de infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (33076, 'Playas', 'La Ñora', 'Arenal de reducidas dimensiones flanqueado por acantilados en uno de sus lados. Ofrece un nivel medio de servicios y un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35002, 'Playas', 'Arinaga', 'La playa Arinaga situada en Agüimes es una playa de arena de 700 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35003, 'Playas', 'Caleta de Fuste', 'La playa Caleta de Fuste situada en Antigua es una playa de arena de 700 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35004, 'Playas', 'El Castillo', 'La playa El Castillo situada en Arrecife es una playa de arena de 30 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35004, 'Playas', 'El Reducto', 'La playa El Reducto situada en Arrecife es una playa de arena de 470 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35004, 'Playas', 'El Cable', 'La playa El Cable situada en Arrecife es una playa de arena de 315 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35006, 'Playas', 'Los Charcones', 'En las proximidades del Puertillo de San Andrés se encuentran los Charcones. La playa Los Charcones situada en Arucas es una playa compuesta de arena, grava y bolos de 175 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35006, 'Playas', 'San Andrés', 'Playa compuesta de arena y bolos de 450 metros de longitud. La cantidad de arena depende mucho de las corrientes y la época del año. En invierno suele contar con menos áridos que en verano. Suele ser ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35011, 'Playas', 'El Burrero', 'La playa El Burrero situada en Ingenio es una playa compuesta de arena y bolos de 500 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35012, 'Playas', 'Amadores', 'La playa Amadores situada en Mogán es una playa de arena de 488 metros de longitud, que cuenta con con numerosos bazares y servicios de restauración.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35012, 'Playas', 'Mogán', 'Playa urbana con numerosos serviios de restauración.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35013, 'Playas', 'Charco San Lorenzo', 'La playa Charco San Lorenzo situada en Moya es una playa de roca de 75 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35013, 'Playas', 'Pagador', 'La playa Pagador situada en Moya es una playa de bolos de 310 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35014, 'Playas', 'El Viejo', 'La playa El Viejo situada en La Oliva es una playa de arena de 1000 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35014, 'Playas', 'Corralejo', 'La playa Corralejo situada en La Oliva es una playa de arena de 195 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35015, 'Playas', 'Sotavento', 'La playa Sotavento situada en Pájara es una playa de arena de 1100 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35016, 'Playas', 'Las Canteras', 'La playa Las Canteras situada en Las Palmas de Gran Canaria es una playa de arena de 2250 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamient', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35017, 'Playas', 'Blanca', 'La playa Blanca situada en Puerto del Rosario es una playa de arena de 875 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35018, 'Playas', 'Honda', 'Formada por dos calas separadas entre si por las casas del Sr. Juan, se comunica con la playa de Guacimeta en Tías.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35028, 'Playas', 'Guacimeta', 'La playa Guasimeta, situada en Tías, es una playa de arena de 1050 metros de longitud. Se comunica con la playa Honda en San Bartolomé.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35028, 'Playas', 'Lima', 'La playa Lima, situada en Tías, es una playa compuesta de arena, roca y grava de 900 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35028, 'Playas', 'Matagorda', 'La playa Matagorda, situada en Tías, es una playa de arena de 840 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35030, 'Playas', 'Las Playitas', 'La playa Las Playitas situada en Tuineje es una playa compuesta de arena y bolos de 700 metros de longitud.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (35030, 'Playas', 'Gran Tarajal', 'La playa Gran Tarajal situada en Tuineje es una playa de arena de 560 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 'verificado_manual', date('now'));
