INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (36035, 'Playas', 'Patos', 'Ubicada en la Ensenada de Carreira, con 1.700 metros de longitud y muy bien equipada.', 'verificado_manual', date('now'));
