INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (36060, 'Playas', 'Bamio', 'Playa situada junto al núcleo urbano de Bamio, de donde toma su nombre.', 'verificado_manual', date('now'));
