INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38001, 'Playas', 'Torviscas', 'Playa unida a la de Fañabé, dotada de excelentes equipaciones y muy visitada por los bañistas, que encuentran en esta zona todo tipo de comodidades.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38001, 'Playas', 'El Bobo', 'Pequeña playa de arena oscura con buenos servicios, ubicada en una zona dotada de todo tipo de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38001, 'Playas', 'La Pinta', 'Resguardada playa con todo tipo de infraestructuras, que la convierten en uno de los principales focos de turismo de esta zona de la isla', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38006, 'Playas', 'Troya', 'Extensa playa del término de Arona, en una de las zonas turísticas por excelencia de la isla de Tenerife.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38006, 'Playas', 'El Camisón', 'Playa resguardada por los espigones que la rodean, y dotada con todo tipo de equipamientos que hacen que presente una elevada afluencia de bañistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38006, 'Playas', 'Las Vistas', 'Extensa playa dotada de todo tipo de servicios e instalaciones hosteleras, situada en una de las zonas más visitadas por el turismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38008, 'Playas', 'Bajamar', 'Playa de arena oscura, que presenta una moderada afluencia de público. Dispone de aseos y duchas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38009, 'Playas', 'Los Cancajos', 'Amplia playa de arena oscura, muy frecuentada por el público y dotada de buenos equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38010, 'Playas', 'Las Arenas', 'Playa característica por su microclima, que la protege de los vientos del noroeste, y por ser de arena desde Junio hasta Noviembre, para en invierno perderla convirtiéndose en una playa de bolos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38011, 'Playas', 'La Viuda', 'Playa aledaña a un polígono industrial, enclavada en un entorno un tanto degradado. No dispone de infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38011, 'Playas', 'Candelaria', 'Playa del bonito pueblo de Candelaria que suele ser bastante visitada por el público. Está formada por arena oscura, como la mayoría de las playas de la isla.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38011, 'Playas', 'La Hornilla', 'Playa urbana, de arena oscura. Ofrece un nivel medio de equipamientos y es bastante frecuentada por los bañistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38012, 'Playas', 'Las Eras', 'Playa de la población de Las Eras, de arena oscura, y que no dispone de infraestructuras salvo el parking cercano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38012, 'Playas', 'Los Roques', 'Esta playa recibe su nombre de los dos roques que la flanquean. En la zona se puede encontrar algún establecimiento hostelero.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38015, 'Playas', 'El Muelle', 'Playa situada junto al Puerto Pesquero, siendo algunas partes de éste también utilizadas para el baño. Reúne buenas condiciones para los bañistas por lo que en verano está muy frecuentada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38015, 'Playas', 'La Caleta de Interián', 'Tranquila playa rodeada de pequeñas edificaciones que presenta unas aceptables condiciones para el baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38017, 'Playas', 'La Tejita', 'Playa de un kilómetro de longitud enclavada en el Paraje Natural Protegido que conforma la llamativa Montaña Roja', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38019, 'Playas', 'Alcalá', 'Playa del pueblo de Alcalá que ofrece un agradable paseo marítimo y aguas tranquilas para disfrutar del baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38020, 'Playas', 'El Puertito', 'Playa pequeña situada en el puerto de Guímar, que dispone de paseo marítimo y ofrece aguas tranquilas al numeroso público que la visita.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38021, 'Playas', 'Santa Catalina', 'Playa amplia con bajo grado de ocupación y de fuerte oleaje. No ofrece ningún tipo de servicio.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38021, 'Playas', 'La Caleta de Hermigua', 'Pequeña cala de arena negra, situada en las cercanías del casco urbano, que presenta un bajo grado de ocupación. Cuenta con aseos y duchas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38022, 'Playas', 'San Marcos', 'Recogida playa urbana, dotada de paseo marítimo y de otros variados servicios, lo que contribuye a la alta afluencia de público que presenta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38023, 'Playas', 'Arenisco', 'Playa con paseo marítimo, buen nivel de servicios y todo tipo de establecimientos hosteleros en las inmediaciones.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38024, 'Playas', 'Puerto Naos', 'Playa de Puerto Naos, dotada de buenos equipamientos, aparcamiento y accesos para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38026, 'Playas', 'El Bollullo', 'Playa en un entorno muy agradable a la que se accede caminando por un sendero desde el parking cercano. Precaución a la hora del baño debido al fuerte oleaje que presenta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38028, 'Playas', 'Martianez', 'Concurrida playa del Puerto de la Cruz, rodeada de un bello entorno de piscinas naturales. Dispone de completos y variados servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38028, 'Playas', 'San Telmo', 'Esta playa es una pequeña cala situada en el Paseo de San Telmo, entre rocas volcánicas. Entre las rocas se forman pequeños charcos cuando baja la marea.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38028, 'Playas', 'El Muelle', 'Playa de reducido tamaño ubicada en los muelles del Puerto de la Cruz. En los alrededores se puede encontrar todo tipo de servicios de hostelería.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38031, 'Playas', 'El Socorro', 'Bonita playa muy frecuentada por los bañistas que dispone de paseo marítimo y parking. Presenta un fuerte oleaje.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38032, 'Playas', 'Tabaiba', 'Playa de reducidas dimensiones que disfruta de aguas tranquilas y de aceptables infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38032, 'Playas', 'La Nea', 'Playa aledaña al Puerto Deportivo de Radazul.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38032, 'Playas', 'Radazul', 'Dos pequeñas playas de reciente creación, con solarium y accesos al mar, de arena fina. Cuenta con todos los servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38033, 'Playas', 'Puerto Espíndola', 'Playa rocosa, rodeada de pequeñas edificaciones y con moderada afluencia de público. No dispone de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38034, 'Playas', 'Las Aguas', 'Rocosa playa no muy frecuentada por sufrir un fuerte oleaje que complica las condiciones para el baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38037, 'Playas', 'Santa Cruz de la Palma', 'Playa de reciente construcción, de arena oscura y variedad de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38038, 'Playas', 'Benijo', 'Playa enclavada en un impresionante paraje protegido.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38040, 'Playas', 'Los Guíos', 'Playa famosa por el acantilado que la rodea con paredes superiores a 300 m y un puerto deportivo con todo tipo de embarcaciones.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38040, 'Playas', 'Santiago', 'Playa de reducidas dimensiones en un entorno altamente urbanizado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38040, 'Playas', 'La Arena', 'Centro turístico del municipio con un buen nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38042, 'Playas', 'Charco de la Araña', 'En las inmediaciones se pueden encontrar algunas instalaciones hosteleras y una piscina municipal.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38043, 'Playas', 'El Pris', 'Playa de reducidas dimensiones cuyas condiciones para el baño son complicadas debido al fuerte oleaje que presenta, por lo que está poco frecuentada por los bañistas', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38045, 'Playas', 'Puerto de Tazacorte', 'Playa de la localidad de Tazacorte con paseo marítimo y que dispone de aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38045, 'Playas', 'Los Tarajales', 'Está ubicada en la localidad de Tazacorte, anexa al puerto. Cuenta con aparcamiento y accesos para discapacitados', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38048, 'Playas', 'Timijiraque', 'Próxima al Puerto de la Estaca, es una de las pocas playas de arena de la Isla. Suele ser frecuentada por surfistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38049, 'Playas', 'El Inglés', 'Situada al pie de un acantilado, y de oscura arena, esta playa presenta un grado medio de ocupación y no dispone de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38049, 'Playas', 'Valle Gran Rey', 'Extensa playa enclavada en un atractivo paisaje, que disfruta de aguas tranquilas y una moderada afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38049, 'Playas', 'Vueltas', 'Pequeña playa urbana de arena oscura que es utilizada para el fondeo de barcos. No dispone de infraestructuras.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38050, 'Playas', 'Vallehermoso', 'Pequeña playa de roca y grava con grado medio de ocupación. Dispone de duchas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (38901, 'Playas', 'La Restinga', 'Playa situada en el pueblecito de pescadores de La Restinga, en el extremo sur de la isla, siendo la base de la flota pesquera de la isla. Sus centros de buceo deportivo permanecen abiertos todo el añ', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39001, 'Playas', 'Luaña', 'Playa de arena fina dorada que denota un grado medio de ocupación. Ofrece un nivel aceptable de servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39006, 'Playas', 'Los Barcos', 'Playa colindante con la de Ris, de arena fina dorada. Cuenta con paseo marítimo y presenta un nivel medio de servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39006, 'Playas', 'El Sable', 'Pequeña playa urbana de arena fina dorada y protegida por las rocas que la rodean. Presenta una alta afluencia de público y un nivel medio de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39011, 'Playas', 'Cuberris', 'Playa ventosa con fuertes corrientes, muy ancha y compuesta por una arena fina dorada de calidad. Cuenta con un paseo marítimo y tiene accesos adaptados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39020, 'Playas', 'Oriñón', 'Playa de más de un kilómetro de longitud de arena dorada y que presenta una alta afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39020, 'Playas', 'Dícido', 'Pequeña playa aislada y tranquila formada por bolos, y que presenta un fuerte oleaje.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39024, 'Playas', 'Comillas', 'Playa situada en el pueblo de Comillas que presenta una alta afluencia de público. Ofrece arena dorada, un agradable paseo marítimo y todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39035, 'Playas', 'La Salvé', 'Playa de gran tamaño situada en Laredo, pueblo muy frecuentado por turistas en la época estival. Presenta un excelente nivel de servicios: duchas, aseos, alquiler de hamacas y Club Náutico.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39040, 'Playas', 'El Rostro', 'Playa de reducido tamaño con escasa afluencia de público, que disfruta de arena dorada y aguas tranquilas. No ofrece ningún tipo de servicio.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39044, 'Playas', 'Cuchía', 'Playa de arena dorada dotada de rampas de acceso para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39044, 'Playas', 'Mogro', 'Playa urbana de arena dorada que presenta una alta afluencia de público. Dispone de paseo marítimo, aseos, duchas y aparcamiento.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39047, 'Playas', 'Trengandín', 'Playa extensa enclavada en un magnífico paisaje montañoso. Presenta un grado medio de ocupación y está dotada con múltiples servicios, incluida la posibilidad de realizar diversos deportes acuáticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39047, 'Playas', 'Ris', 'Playa de arena dorada y fuertes vientos enclavada en un entorno agradable. Presenta un buen nivel de equipamientos: duchas, aseos, alquiler de hamacas y alquileres náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39052, 'Playas', 'Canallave', 'Playa de mar abierto, ventosa y con fuertes corrientes, lo que hace que sea bastante peligrosa. Presenta un grado medio de ocupación y ofrece algunos servicios. Es muy frecuentada por surfistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39052, 'Playas', 'Valdearenas', 'Playa ubicada en el Parque Natural de las Dunas de Liencres. Hay que tener precaución a la hora del baño ya que está en mar abierto, tiene fuertes corrientes y se generan remolinos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39061, 'Playas', 'Galizano', 'Playa aislada enclavada en un entorno rocoso con vegetación, de arena fina dorada y fuerte oleaje. Presenta un grado medio de ocupación y un bajo nivel de equipamientos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39068, 'Playas', 'Ensenada de Fonfría', 'Playa rocosa poco recomendada para el baño', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39073, 'Playas', 'San Juan de la Canal', 'Playa semiurbana de arena dorada y de fuertes vientos. Cuenta con un agradable paseo marítimo y un nivel medio de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39075, 'Playas', 'La Magdalena', 'Playa urbana que ofrece arena dorada, aguas tranquilas y multitud de servicios: aseos, duchas, alquiler de hamacas y la posibilidad de realizar diversos deportes acuáticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39075, 'Playas', 'Los Peligros', 'Playa urbana que denota una alta afluencia de público. Ofrece arena dorada, aguas tranquilas, zona de fondeo y multitud de servicios: aseos, duchas, alquiler de hamacas y la posibilidad de realizar di', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39075, 'Playas', 'Los Bikinis', 'Playa enclavada en la bahía de Santander, a la que se accede a través de los jardines de la Magdalena. Ofrece arena fina dorada y aguas tranquilas y un nivel aceptable de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39076, 'Playas', 'Santa Justa', 'Playa de reducido tamaño compuesta por arena y bolos. Tiene escasa afluencia de público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39079, 'Playas', 'San Martín', 'Playa de aguas tranquilas formada por una extensa y estrecha franja de arena a lo largo del pueblo de Santoña. Dispone de paseo marítimo y zona de fondeo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39079, 'Playas', 'Berria', 'Extensa playa semiurbana de arena dorada y buen nivel de servicios en el Parque natual de las Marismas de Santoña, Victoria y Joyel.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39080, 'Playas', 'El Cabo', 'Playa aislada muy frecuentada por surfistas debido al fuerte oleaje y los vientos que la caracterizan. No ofrece al visitante ningún tipo de servicio.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39080, 'Playas', 'Merón', 'Playa semiurbana con un grado medio de ocupación. Ofrece fina arena blanca, y está dotada con todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39080, 'Playas', 'El Tostadero', 'Playa semiurbana que ofrece fina arena dorada, y está dotada con todo tipo de servicios. Existe la posibilidad de realizar diferentes deportes, incluidos los acuáticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39085, 'Playas', 'La Ribera', 'Pequeña playa urbana que presenta un grado medio de ocupación. Ofrece arena dorada, aguas tranquilas y un nivel medio de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39085, 'Playas', 'La Concha', 'Playa de un kilómetro de longitud situada en la parte bajal pueblo. Dispone de paseo marítimo y un buen nivel de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (39091, 'Playas', 'Oyambre', 'Playa muy extensa ubicada dentro del Parque Natural de Oyambre, en la que se combinan las dunas con la vegetación. Se encuentra bastante aislada a pesar de lo cual está bastante frecuentada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43004, 'Playas', 'Mar-i-Cel', 'Playa compuesta de grava y arena, aislada de núcleos urbanos y con total ausencia de instalaciones y servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43004, 'Playas', 'El Ciment', 'Esta playa recibe el nombre de El Ciment por estar situada junto a una fábrica de cemento que caracteriza el entorno donde está ubicada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43012, 'Playas', 'Altafulla', 'Playa que dispone de acceso para discapacitados y alquileres de embarcaciones náuticas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43013, 'Playas', 'Cala Pepo', 'Cala de pequeñísimo tamaño ubicada en una zona urbana, compuesta de grava y arena que goza de unas aguas tranquilas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43013, 'Playas', 'L''Alguer', 'Playa de arena dorada ubicada en el mismo casco urbano de L''Ametlla.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43013, 'Playas', 'Cala Llobeta', 'Estas calas de dorada y fina arena son las principales protagonistas de esta costa, donde se puede oler el aroma de los pinares que acarician el agua.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43014, 'Playas', 'Los Eucaliptos', 'Esta playa se caracteriza por ser virgen a la acción del hombre, de espacios abiertos, arena fina, flora peculiar y autóctona y las singulares dunas de arena, que hacen del Delta un paraje insólito.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43037, 'Playas', 'Calafell', 'Playa de arena dorada con una extensión aproximada de un kilómetro ubicada en una zona urbana con un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43037, 'Playas', 'Mas Mel', 'Esta playa dispone de alquiler de sombrillas, hamacas, embarcaciones náuticas y todo tipo de instalaciones para el uso del público.', 'verificado_manual', date('now'));

INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43037, 'Playas', 'Segur de Calafell', 'Esta playa alberga el Puerto Marítimo de Segur de Calafell y presenta gran cantidad de servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43038, 'Playas', 'Cap de Sant Pere', 'Esta playa de arena y aguas tranquilas presenta un alto grado de ocupación y dispone de alquiler de hamacas y sombrillas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43038, 'Playas', 'L''Ardiaca', 'Playa de carácter urbano compuesta de grava y arena que dispone de variedad de servicios y alquileres de hamacas y sombrillas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43038, 'Playas', 'La Llosa', 'Playa de grava y arena con inmejorables servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43050, 'Playas', 'Creixell', 'Playa de unos dos kilómetros de longitud de arena fina que dispone de todo tipo de servicios e instalaciones.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43051, 'Playas', 'Cunit', 'Se extiende a lo largo de dos kilómetros y medio de arena dorada donde se puede disfrutar de instalaciones y servicios múltiples. La playa consta de 7 espigones (de sur a norte): Can Toni, Les sorres,', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43092, 'Playas', 'Punta del Riu', 'Playa de arena y aguas tranquilas donde pueden practicarse todo tipo de deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43092, 'Playas', 'Platja de Cristall', 'Playa de arena donde pueden practicarse deportes náuticos y el submarinismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43104, 'Playas', 'Cala Buena', 'Playa de reducidas dimensiones de arena y grava fina ubicada en una zona semiurbana y tranquila.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43104, 'Playas', 'Santa Llúcia', 'Playa con un alto grado de ocupación compuesta de arena dorada y gravilla ubicada en una zona semiurbana. En esta playa se sitúa el conocido Morro del Gos, un islote de dimensiones reducidas que forma', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43131, 'Playas', 'Platja Llarga', 'Playa con un elevado grado de ocupación durante la temporada estival que dispone de servicios e instalaciones para su uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43131, 'Playas', 'Punta de la Guineu', 'Playa urbana donde pueden alquilarse hamacas y embarcaciones deportivas y que dispone de un club náutico en la misma playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43131, 'Playas', 'La Pelliseta', 'Esta playa presenta un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43136, 'Playas', 'Suizo', 'Dos pequeñas playas de arena dorada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43136, 'Playas', 'Les Delicies', 'Playa ubicada en el núcleo urbano, con alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43136, 'Playas', 'El Faro', 'Playa compuesta de arena ubicada en una zona urbana y con un elevado grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43148, 'Playas', 'El Milagro', 'Playa de fina arena y suave pendiente que goza de unas aguas tranquilas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43148, 'Playas', 'L''Arrabassada', 'Playa de carácter semiurbano que presenta un elevado grado de ocupación durante la temporada alta.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43148, 'Playas', 'La Savinosa', 'Playa compuesta de fina arena dorada donde puede disfrutarse de unas tranquilas aguas y un entorno de vegetación natural.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43153, 'Playas', 'Barrio Marítimo', 'Playa situada en el antiguo barrio de pescadores y va desde la plaza de Narcís Monturiol hasta el Club Marítimo y a su lado esta ubicado el Paseo Marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43153, 'Playas', 'El Muntanyans', 'Playa de gran extensión que alberga un ecosistema dunar típico de costa con dunas semimóviles y lagunas de agua salada, por lo que está incluida en el Plan de Espacios de Interés Natural.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43153, 'Playas', 'La Paella', 'Playa situada en la urbanización dels Munts que alberga el puerto deportivo y pesquero y tiene una zona destinada a la práctica deportiva. Dispone de servicios e instalaciones de calidad.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43162, 'Playas', 'L''Almadrava', 'Playa extensa de arena dorada ubicada en una zona semiurbana, que se caracteriza por sus aguas tranquilas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43162, 'Playas', 'El Torn', 'La Platja del Torn se caracteriza por su entorno natural que representa un paraíso para las vacaciones naturistas de las familias que buscan la tranquilidad, naturaleza y servicios de alto nivel.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43163, 'Playas', 'El Francàs', 'Playa de arena fina y aguas tranquilas de algo más de un kilómetro de extensión, ubicada en una zona urbana y con un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43163, 'Playas', 'Coma-Ruga', 'La Playa de Coma Ruga dispone de todo tipo de servicios e instalaciones, así como el Puerto Deportivo en la misma playa y un Club Náutico.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43163, 'Playas', 'Sant Salvador', 'Playa de arena de carácter urbano, equipada con gran cantidad de instalaciones y servicios para el uso del público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43171, 'Playas', 'La Pineda', 'Playa de gran extensión, con inmejorables servicios e instalaciones de todo tipo, incluida una zona reservada para la práctica del submarinismo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43901, 'Playas', 'Riumar', 'Playa ubicada a unos ocho kilómetros del núcleo urbano de Deltebre, en el mismo Parc Natural del Delta D''Ebre, que goza de todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43901, 'Playas', 'La Marquesa', 'Playa extensa y tranquila, sin masificaciones, ubicada en un bello paraje natural.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43905, 'Playas', 'Playa de Poniente', 'Playa natural de fina y dorada arena de suave pendiente que confiere gran seguridad para los bañistas y los niños. Dispone de una zona infantil para juegos y de una zona reservada para los deportes ná', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43905, 'Playas', 'Playa de Levante', 'Es la playa natural de mayor extensión del municipio que dispone de acceso para discapacitados, zona infantil para juegos, zona deportiva y deportes náuticos, además de un gran número de servicios e i', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43905, 'Playas', 'Els Capellans', 'Es una pequeña playa situada en el núcleo urbano, de suave pendiente y muy segura. Dispone de gran cantidad de servicios e instalaciones, así como de una zona reservada para deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43906, 'Playas', 'El Arenal', 'Destaca por su arena fina y dorada típica de las playas del Delta. Debido a su situación, es una playa ideal para los niños por su poca profundidad. Conocida como "la playa de la calma".', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43906, 'Playas', 'El Arquitecto', 'Pequeña playa localizada al abrigo del Puerto Deportivo de L''Ampolla, al final del paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (43906, 'Playas', 'Les Avellanes', 'Pequeña playa ubicada en el centro urbano que destaca por su arena y aguas tranquilas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46013, 'Playas', 'Port-Saplaya Norte', 'Playa familiar con buenos accesos y puerto deportivo cercano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46013, 'Playas', 'Patacona', 'Playa totalmente equipada con servicios de todo tipo. Dispone de un camping privado.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46048, 'Playas', 'Bellreguard', 'Playa de Bellreguard, de arena dorada, ubicada en una zona urbana y un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46082, 'Playas', 'Racó de Mar', 'Playa de gran calidad, tanto por su composición y sus características como por las instalaciones que presenta, incluidos los accesos para discapacitados.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46105, 'Playas', 'El Faro', 'Playa indicada para realizar buceo que recibe su nombre por encontrarse cercana al faro de Cullera, en una zona muy urbanizada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46105, 'Playas', 'Los Olivos', 'Playa de calidad por su excelente arena y disponibilidad de servicios, muy concurrida en la época estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46105, 'Playas', 'Mareny de Sant Llorenç', 'Playa situada en el Parque Natural de La Albufera, de gran extensión, donde la gran mayoría de los accesos son de tipo privado y sin equipo de vigilancia ni señalizaciones de peligro.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46113, 'Playas', 'Los Pedregales', 'Playa familiar dotada de todos los servicios y protegida por un parque e instalaciones deportivas que anteceden a un cordón dunar.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46113, 'Playas', 'Daimús', 'Es la playa más concurrida del término de Daimús, de arena y con disponibilidad de servicios y equipamientos. Dispone de camping cercano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46131, 'Playas', 'L''Ahuir', 'Playa aislada pero con todo tipo de servicios disponibles y apta para la práctica de deportes náuticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46131, 'Playas', 'Norte de Gandía', 'Es la playa de Gandía por excelencia, ubicada en una zona urbana con excelentes equipamientos y servicios y una gran actividad a lo largo de toda la playa.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46131, 'Playas', 'Venecia', 'Playa dotada de los servicios más elementales, ubicada en una zona urbana y que disfruta de unas aguas tranquilas para el baño.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46140, 'Playas', 'Guardamar', 'Playa que presenta buena calidad en sus aguas y arenas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46143, 'Playas', 'Xeraco', 'Playa con mediana ocupación y gran cantidad de servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46168, 'Playas', 'Miramar', 'Esta playa de gran extensión de arena y aguas tranquilas acoge a gran cantidad de visitantes en la época estival.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46181, 'Playas', 'Terra Nova', 'Playa situada al norte del municipio rodeada por cordones dunares.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46181, 'Playas', 'Pau Pi', 'Playa de aguas tranquilas y fina arena. Dispone de acceso para discapacitados y una zona adaptada.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46181, 'Playas', 'L''Aigua Blanca', 'Playa extensa de fina arena con excelentes servicios y zona habilitada para la práctica de Kite-Surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46195, 'Playas', 'Piles', 'Tranquila playa de arena fina y aguas tranquilas que alberga, principalmente, veraneantes locales.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46199, 'Playas', 'La Pobla de Farnals', 'Playa urbana de arena dotada de todo tipo de servicios de calidad, con un alto grado de ocupación.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46204, 'Playas', 'Puig-Val', 'Playa delimitada por espigones que impiden el fuerte oleaje. Mezcla la arena fina con cantos rodados en algunos tramos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46204, 'Playas', 'Torreta de Santa Elvira', 'Playa muy antropizada y delimitada por una sucesión de espigones', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46205, 'Playas', 'Puçol', 'Playa con amplia oferta de infraestructuras, servicios y actividades, sobre todo en los meses de verano.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46220, 'Playas', 'Corint', 'Playa de gran extensión', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46220, 'Playas', 'L''Almardà', 'Gran extensión de arena fina de playa, con presencia de gravas en algunos tramos, que dispone de los servicios más elementales para el uso público.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46220, 'Playas', 'Port de Sagunt', 'Playa urbana localizada en el mismo Grao de Sagunto, de arena dorada y con disponibilidad de todo tipo de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46235, 'Playas', 'El Perelló', 'Playa urbana con servicios disponibles que presenta un punto negro de contaminación representado por la Gola del mismo nombre.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46235, 'Playas', 'Les Palmeres', 'Les PalmerEs presenta un alto grado de ocupación, sobre todo en época estival, debido a su cercanía a una zona urbana y a la cantidad de servicios disponibles.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46235, 'Playas', 'El Rey', 'Playa situada en pleno Parque Natural de la Albufera con escasos servicios', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46238, 'Playas', 'Tavernes', 'Playa con un tramo urbano, muy concurrida en fines de semana y verano. Dispone de multitud de servicios.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46238, 'Playas', 'Goleta', 'Playa de carácter familiar con un moderado desarrollo urbanístico.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46250, 'Playas', 'Pinedo', 'Playa al sur de Valencia que dispone de accesos para discapacitados, además de servicios elementales para su uso público, biblioteca de playa y zona de mascotas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46250, 'Playas', 'El Saler', 'Playa situada en pleno corazón del Parque Natural de la Albufera. De arena fina y dorada, está protegida de los vientos de poniente por las dunas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (46250, 'Playas', 'Les Devesses', 'Situada en pleno Parque Natural de La Albufera, es la única playa salvaje del municipio y la que goza de mayor protección ambiental por su entorno natural', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48012, 'Playas', 'Bakio', 'Playa urbana, que presenta un alto grado de ocupación. Dispone de un agradable paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48014, 'Playas', 'Muriola', 'Playa pequeña y bien protegida, que fue generada artificialmente por la arena silícea de una cantera cercana.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48017, 'Playas', 'Aritxatxu', 'Playa de reducidas dimensiones, muy protegida por las grandes rocas que la rodean. Se encuentra situada dentro de la Reserva de la Biosfera de Urdaibai.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48021, 'Playas', 'San Antonio', 'Playa situada en la margen izquierda de la ría, dentro de la Reserva de la Biosfera de Urdaibai. Ofrece arena fina, aguas tranquilas y un pequeño paseo marítimo.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48028, 'Playas', 'Ea', 'Playa urbana en la desembocadura de la Ría del Municipio. Muy abrigada. Ofrece fina arena.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48043, 'Playas', 'Gorliz', 'Playa semiurbana que presenta un alto grado de ocupación. Presenta un buen nivel de servicios: duchas, aseos, y ofrece la posibilidad de realizar en ella diferentes deportes acuáticos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48044, 'Playas', 'Gorrondatxe', 'Playa enclavada en un entorno natural atractivo, con amplio fondo, compuesta por arena y rocas. Es frecuentada por surfistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48044, 'Playas', 'Barinatxe', 'Playa aislada y enclavada en un atractivo entorno montañoso. Disfruta de una arena fina dorada, y es muy frecuentada por surfistas.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48044, 'Playas', 'Las Arenas', 'Pequeño arenal ubicado en entorno urbano, cuenta con un club marítimo de gran tradición y numerosos servicios hoteleros', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48048, 'Playas', 'Laida', 'Playa extensa, que presenta una gran afluencia de público. Ofrece un buen nivel de equipamientos, y la posibilidad de realizar diversos deportes acuáticos. Pertenece a la Reserva de la Biosfera de Urd', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48048, 'Playas', 'Laga', 'Playa aislada, que presenta una alta afluencia de público, pero a pesar de esto goza de una cierta tranquilidad. Está enclavada dentro de la Reserva de la Biosfera de Urdaibai.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48049, 'Playas', 'Ogella', 'Playa aislada, compuesta por bolos. Es habitual en ella la práctica del surf.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48056, 'Playas', 'Armintza', 'Pequeña playa rocosa, que presenta una escasa afluencia de público, en su mayoría está compuesto por submarinistas atraídos por sus interesantes fondos marinos.', 'verificado_manual', date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine, tipo, nombre, descripcion, fuente, fecha_ingesta) VALUES (48057, 'Playas', 'Isuntza', 'Playa colindante con el puerto de Lekeitio, que presenta gran afluencia de público. Ofrece fina arena, aguas tranquilas, y un buen nivel de equipamientos.', 'verificado_manual', date('now'));
